&lt;style&gt;span.Cat&#233;gorie { display:none; }&lt;/style&gt;&lt;div class=&quot;presentation navmenu&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Acc&#232;s rapide aux sections sur l&#39;&#233;quipement&lt;a class=&quot;headeranchor&quot; id=&quot;Acc&#232;s_rapide_aux_sections_sur_l&#233;quipement_0&quot; href=&quot;#Acc&#232;s_rapide_aux_sections_sur_l&#233;quipement_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;table&gt;&lt;tr style=&quot;vertical-align: top; text-align: left&quot;&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armes.html&quot; title=&quot;Tableau r&#233;capitulatif des armes&quot;&gt;Les armes&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Armes.html&quot; title=&quot;Descriptions individuelles des armes&quot;&gt;descriptions&lt;/a&gt;)&lt;/li&gt;
	&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes.html&quot; title=&quot;Caract&#233;ristiques des armes&quot;&gt;caract&#233;ristiques&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armes-&#192;-Feu.html&quot; title=&quot;Tableau r&#233;capitulatif des armes &#224; feu&quot;&gt;Les armes &#224; feu&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Armes-&#192;-Feu.html&quot; title=&quot;Descriptions individuelles des armes &#224; feu&quot;&gt;descriptions&lt;/a&gt;)&lt;/li&gt;
	&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;caract&#233;ristiques&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures.html&quot; title=&quot;Tableau r&#233;capitulatif des armures&quot;&gt;Les armures&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Armures.html&quot; title=&quot;Descriptions individuelles des armures&quot;&gt;descriptions&lt;/a&gt;)&lt;/li&gt;
	&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures.html&quot; title=&quot;Caract&#233;ristiques des armures&quot;&gt;caract&#233;ristiques&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux.html&quot; title=&quot;Les mat&#233;riaux sp&#233;ciaux&quot;&gt;Les mat&#233;riaux sp&#233;ciaux&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Animaux,%20montures%20et%20leur%20%C3%A9quipement.ashx#&quot; title=&quot;Animaux, montures et leur &#233;quipement&quot;&gt;Animaux, montures et leur &#233;quipement&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chroniques-Des-&#201;claireurs.html&quot; title=&quot;Chroniques des Explorateurs&quot;&gt;Chroniques des Explorateurs&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;%C3%89quipement%20daventurier.ashx#&quot; title=&quot;&#201;quipement d&amp;#39;aventurier&quot;&gt;&#201;quipement d&#39;aventurier&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Focalisateurs%20de%20canalisation.ashx#&quot; title=&quot;Focalisateurs de canalisation&quot;&gt;Focalisateurs de canalisation&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;H%C3%A9bergement%20et%20services.ashx#&quot; title=&quot;H&#233;bergement et services&quot;&gt;H&#233;bergement et services&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Jeux.ashx#&quot; title=&quot;Jeux&quot;&gt;Jeux&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;March%C3%A9%20noir.ashx#&quot; title=&quot;March&#233; noir&quot;&gt;March&#233; noir&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moyens%20de%20transport.ashx#&quot; title=&quot;Moyens de transport&quot;&gt;Moyens de transport&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nourriture%20et%20Boissons.ashx#&quot; title=&quot;Nourriture et Boissons&quot;&gt;Nourriture et Boissons&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Outils%20de%20comp%C3%A9tences.ashx#&quot; title=&quot;Outils de comp&#233;tences&quot;&gt;Outils de comp&#233;tences&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Trousses%20d%C3%A9quipement.ashx#&quot; title=&quot;Trousses d&amp;#39;&#233;quipement&quot;&gt;Trousses d&#39;&#233;quipement&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;V%C3%AAtements.ashx#&quot; title=&quot;V&#234;tements&quot;&gt;V&#234;tements&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poisons.ashx#&quot; title=&quot;Les poisons  &quot;&gt;Poisons&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armes%20alchimiques.ashx#&quot; title=&quot;Armes alchimiques&quot;&gt;Armes alchimiques&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Outils%20alchimiques.ashx#&quot; title=&quot;Outils alchimiques&quot;&gt;Outils alchimiques&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rem%C3%A8des%20alchimiques.ashx#&quot; title=&quot;Rem&#232;des alchimiques&quot;&gt;Rem&#232;des alchimiques&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Argent-Et-Richesse.html&quot; title=&quot;Argent et richesse&quot;&gt;L&#39;argent et la richesse&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marchandises.html&quot; title=&quot;Marchandises&quot;&gt;Les marchandises&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poids-Transportable.html&quot; title=&quot;Poids transportable&quot;&gt;Le poids transportable&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;actifs-Alchimiques.html&quot; title=&quot;R&#233;actifs alchimiques&quot;&gt;Les r&#233;actifs alchimiques&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;i&gt;Les armes d&#233;crites ci-dessous sont celles pr&#233;sent&#233;es dans le &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armes.html&quot; title=&quot;Tableau r&#233;capitulatif des armes&quot;&gt;tableau r&#233;capitulatif des armes&lt;/a&gt;. Les armes &#224; aspersion sont d&#233;crites dans la section &lt;a class=&quot;pagelink&quot; href=&quot;Armes-Alchimiques.html&quot; title=&quot;Armes alchimiques&quot;&gt;Armes alchimiques&lt;/a&gt;.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Les armes marqu&#233;es d&#39;un ast&#233;risque (*) sont des &lt;a class=&quot;pagelink&quot; href=&quot;Armes-Orientales.html&quot; title=&quot;Armes et armures orientales&quot;&gt;armes orientales&lt;/a&gt;.  
Les armes marqu&#233;es de deux ast&#233;risques (**) sont des &lt;a class=&quot;pagelink&quot; href=&quot;Armes-Et-Armures-Primitives.html&quot; title=&quot;Armes et armures primitives&quot;&gt;armes primitives&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Armes courantes&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_courantes_13&quot; href=&quot;#Armes_courantes_13&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;h3 class=&quot;separator&quot;&gt;Combat &#224; mains nues&lt;a class=&quot;headeranchor&quot; id=&quot;Combat_&#224;_mains_nues_0&quot; href=&quot;#Combat_&#224;_mains_nues_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Mains nues&quot; href=&quot;#Mains nues&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Mains nues.&lt;/b&gt; Une &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples.html#ATTAQUEMAINSNUES&quot; title=&quot;Actions simples&quot;&gt;attaque &#224; mains nues&lt;/a&gt; est une attaque telle qu’un coup de poing ou un coup de pied port&#233; par un attaquant ne portant pas d’arme. Un personnage de taille M inflige 1d3 points de d&#233;g&#226;ts &lt;a class=&quot;pagelink&quot; href=&quot;Blessures-Et-Mort.html#NONLETAL&quot; title=&quot;Blessures et mort&quot;&gt;non l&#233;taux&lt;/a&gt; avec une attaque &#224; mains nues. Un personnage de taille P inflige 1d2 points de d&#233;g&#226;ts non l&#233;taux.&lt;br/&gt;&lt;br/&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt; ou tout personnage ayant le don &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Combat-&#192;-Mains-Nues.html&quot; title=&quot;Science du combat &#224; mains nues&quot;&gt;Science du combat &#224; mains nues&lt;/a&gt; peut infliger des d&#233;g&#226;ts l&#233;taux ou non l&#233;taux avec une attaque &#224; mains nues, selon ce qu’il d&#233;cide. Les d&#233;g&#226;ts d’une attaque &#224; mains nues sont consid&#233;r&#233;s comme des d&#233;g&#226;ts d’arme en ce qui concerne les effets qui donnent un bonus aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; avec une arme.&lt;br/&gt;&lt;br/&gt;Une attaque &#224; mains nues est toujours consid&#233;r&#233;e comme une &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armelegere.html&quot; title=&quot;arme l&#233;g&#232;re&quot;&gt;arme l&#233;g&#232;re&lt;/a&gt;. Ainsi, le personnage peut utiliser le don &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Finesse.html&quot; title=&quot;Attaque en finesse&quot;&gt;Attaque en finesse&lt;/a&gt; pour appliquer son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; plut&#244;t que son modificateur de Force &#224; ses jets d’attaque &#224; mains nues.&lt;br/&gt;&lt;br/&gt;Les attaques &#224; mains nues ne comptent pas comme des &lt;a class=&quot;pagelink&quot; href=&quot;Attaques-Naturelles-(Capacit&#233;).html&quot; title=&quot;Attaques naturelles&quot;&gt;armes naturelles&lt;/a&gt;. On ne peut pas &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Desarmement.html&quot; title=&quot;d&#233;sarmement&quot;&gt;d&#233;sarmer&lt;/a&gt; un personnage qui porte des attaques &#224; mains nues.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Armes de corps &#224; corps l&#233;g&#232;res&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_de_corps_&#224;_corps_l&#233;g&#232;res_1&quot; href=&quot;#Armes_de_corps_&#224;_corps_l&#233;g&#232;res_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot; style=&quot;padding-right:10px&quot;&gt;
&lt;script&gt;
$(function () {
  let image = &quot;Illustrations/PNJ/Kobold.jpg&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;.symbole2&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td class=&quot;symbole2&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux membres de la race indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Kobold (race).ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/Illustrations/PNJ/Kobold.jpg&quot; width=&quot;80%&quot; style=&quot;float:center; margin: 0px -50px 0px 7px; border: 1px solid #4b3124&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br /&gt;commune chez&lt;br /&gt;les &lt;a class=&quot;pagelink&quot; href=&quot;Kobold-(Race).html&quot; title=&quot;Les kobolds&quot;&gt;kobolds&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Accessoires caudaux kobolds&quot; href=&quot;#Accessoires caudaux kobolds&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Accessoires caudaux kobolds.&lt;/b&gt; Un kobold ayant le don &lt;a class=&quot;pagelink&quot; href=&quot;Queue-De-Terreur.html&quot; title=&quot;Queue de terreur&quot;&gt;Queue de terreur&lt;/a&gt; peut fixer ces accessoires sur le bout de sa queue pour am&#233;liorer son attaque naturelle. Chaque accessoire caudal fournit juste assez de poids, d’&#233;quilibre et de puissance de frappe pour augmenter les d&#233;g&#226;ts de son coup de queue. Il faut une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt; pour fixer un accessoire caudal de kobold, et celui-ci re&#231;oit un bonus de +4 contre les tentatives de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Desarmement.html&quot; title=&quot;d&#233;sarmement&quot;&gt;d&#233;sarmement&lt;/a&gt; visant &#224; d&#233;tacher son accessoire caudal.&lt;br/&gt;&lt;br/&gt;Lorsqu’un kobold porte un accessoire caudal, l’attaque inflige les d&#233;g&#226;ts de l’accessoire caudal et certains b&#233;n&#233;ficient d’une caract&#233;ristique sp&#233;ciale. Les accessoires caudaux sont des armes l&#233;g&#232;res et peuvent &#234;tre am&#233;lior&#233;s avec des dons augmentant les attaques d’arme (comme &lt;a class=&quot;pagelink&quot; href=&quot;Arme-De-Pr&#233;dilection.html&quot; title=&quot;Arme de pr&#233;dilection&quot;&gt;Arme de pr&#233;dilection&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Sp&#233;cialisation-Martiale.html&quot; title=&quot;Sp&#233;cialisation martiale&quot;&gt;Sp&#233;cialisation martiale&lt;/a&gt;). Tous les accessoires caudaux de kobold forment un &lt;a class=&quot;pagelink&quot; href=&quot;Groupe-Darmes.html&quot; title=&quot;Les groupes d&amp;#39;arme du guerrier&quot;&gt;groupe d’armes&lt;/a&gt; pouvant &#234;tre am&#233;lior&#233;es par la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#ENTRAINEMENTAUXARMES&quot; title=&quot;Le guerrier&quot;&gt;entra&#238;nement aux armes&lt;/a&gt; du guerrier. Ils peuvent &#234;tre d’un &lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux.html&quot; title=&quot;Les mat&#233;riaux sp&#233;ciaux&quot;&gt;mat&#233;riau sp&#233;cial&lt;/a&gt; et fabriqu&#233;s comme des &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html#OBJETMAITRE&quot; title=&quot;Artisanat&quot;&gt;objets de ma&#238;tre&lt;/a&gt; ou magiques. Il y a cinq types d’accessoires caudaux de base.
&lt;ul&gt;&lt;li&gt;&lt;i&gt;Balai.&lt;/i&gt; Correctement utilis&#233;e, cette pi&#232;ce de m&#233;tal tr&#232;s incurv&#233;e peut renverser les adversaires. Il co&#251;te 7 po, inflige 1d4 points de d&#233;g&#226;ts contondants (1d6 en taille M), a un multiplicateur de critique de &#215;2, p&#232;se 1,5 kg et poss&#232;de l’attribut sp&#233;cial &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes.html#CROCENJAMBE&quot; title=&quot;Caract&#233;ristiques des armes&quot;&gt;croc-en-jambe&lt;/a&gt;. Contrairement &#224; la plupart des armes de croc-en-jambe, le kobold ne peut pas la l&#226;cher s’il tombe lors de sa propre tentative de croc-en-jambe.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Lame.&lt;/i&gt; Ce morceau de m&#233;tal a une ar&#234;te couverte de piquants. Elle co&#251;te 3 po, inflige 1d6 points de d&#233;g&#226;ts tranchants (1d8 en taille M), a un multiplicateur de critique de 19-20/&#215;2 et p&#232;se 1 kg.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Long fouet.&lt;/i&gt; Cette fine corde est incrust&#233;e de tout petits bouts de verre et de pierre sur toute la longueur. Il co&#251;te 15 po, inflige 1d4 points de d&#233;g&#226;ts tranchants (1d6 en taille M), a un multiplicateur de critique de &#215;2, p&#232;se 0,5 kg et poss&#232;de l’attribut sp&#233;cial &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes.html#ALLONGE&quot; title=&quot;Caract&#233;ristiques des armes&quot;&gt;allonge&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Pieu.&lt;/i&gt; Ce pieu &#233;troit se termine en une pointe ac&#233;r&#233;e. Il co&#251;te 3 po, inflige 1d6 points de d&#233;g&#226;ts perforants (1d8 en taille M), a un multiplicateur de critique de &#215;3 et p&#232;se 1 kg.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Poids.&lt;/i&gt; Cette boule ramass&#233;e est faite dans une sorte de m&#233;tal terne. Il co&#251;te 1 po, inflige 1d6 points de d&#233;g&#226;ts contondants (1d8 en taille M), a un multiplicateur de critique de &#215;2 et p&#232;se 2 kg.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Ceste&quot; href=&quot;#Ceste&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Ceste.&lt;/b&gt; Le ceste est un gant de cuir ou de tissu &#233;pais recouvrant la main du porteur du milieu des doigts au milieu de l’avant-bras. Cette arme de combat rapproch&#233; est renforc&#233;e de plaques de m&#233;tal au niveau des doigts et souvent par&#233;e de pointes vicieuses au niveau du dos de la main et du poignet. Lorsqu’il porte un ceste, le personnage est consid&#233;r&#233; comme &#233;tant arm&#233; et ses  &lt;a class=&quot;pagelink&quot; href=&quot;Mains-Nues-(Arme).html&quot; title=&quot;Mains nues&quot;&gt;attaques &#224; mains nues&lt;/a&gt; infligent des d&#233;g&#226;ts l&#233;taux. S’il est form&#233; au maniement du ceste, ses attaques &#224; mains nues peuvent infliger des d&#233;g&#226;ts contondants ou perforants. Les &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moines&lt;/a&gt; sont form&#233;s au maniement du ceste. Lorsque le personnage utilise un ceste, ses doigts sont en grande partie libres, ce qui lui permet de manier ou de tenir des objets avec cette main, mais la pression que l’arme exerce sur les jointures lui donne un malus de -2 &#224; tous ses tests bas&#233;s sur la pr&#233;cision impliquant l’utilisation de sa main (comme ouvrir des serrures). Il n’est pas possible de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Desarmement.html&quot; title=&quot;d&#233;sarmement&quot;&gt;d&#233;sarmer&lt;/a&gt; un personnage &#233;quip&#233; d’un ceste.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Coup-de-poing&quot; href=&quot;#Coup-de-poing&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Coup-de-poing.&lt;/b&gt; Ces armes s&#39;enfilent parfaitement autour des jointures de la main et permettent au personnage d&#39;infliger des d&#233;g&#226;ts l&#233;taux avec des attaques &#224; mains nues. Il peut tenir, mais pas manier, une arme ou un autre objet dans la main portant le coup-de-poing. Il peut lancer des sorts &#224; composantes gestuelles lorsqu&#39;il porte un coup-de-poing s&#39;il r&#233;ussit un test de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 10 + niveau du sort lanc&#233;). Les &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moines&lt;/a&gt; sont form&#233;s au maniement des coups-de-poings. Ces armes ne peuvent pas faire l&#39;objet d&#39;un &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Desarmement.html&quot; title=&quot;d&#233;sarmement&quot;&gt;d&#233;sarmement&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Pirates de la Mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Pirates of the Inner Sea/Pirates de la Mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoPMI.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Couteau de cuivre&quot; href=&quot;#Couteau de cuivre&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Couteau de cuivre.&lt;/b&gt; Souvent, les pirates portent de longs couteaux de cuivre qu’ils utilisent lors de leurs travaux &#224; bord d’un navire. M&#234;me si la lame de cuivre n’est pas aussi aff&#251;t&#233;e qu’une m&#234;me lame en m&#233;tal, la rouille ne peut pas l’ab&#238;mer. Un pirate peut manier son couteau de cuivre en dernier recours pour se battre mais il est surtout utilis&#233; pour trancher les cordages, &#233;cailler les poissons et diverses autres t&#226;ches.&lt;br/&gt;&lt;br/&gt;Un couteau de cuivre est dot&#233; d&#39;attribut sp&#233;cial &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes.html#FRAGILE&quot; title=&quot;Caract&#233;ristiques des armes&quot;&gt;fragile&lt;/a&gt;. Une arme fragile est affubl&#233;e de l’&#233;tat pr&#233;judiciable &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Bris&#233;.html&quot; title=&quot;Bris&#233;&quot;&gt;bris&#233;&lt;/a&gt; si celui qui le manie obtient un 1 naturel sur un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d’attaque&lt;/a&gt; effectu&#233; avec cette arme. Si une arme fragile est d&#233;j&#224; bris&#233;e, un autre 1 naturel provoque sa destruction.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;50%&quot; style=&quot;vertical-align:top; border-left:solid 1px #002564; padding-left:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Pirates de la Mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Pirates of the Inner Sea/Pirates de la Mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoPMI.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Crochet de pirate&quot; href=&quot;#Crochet de pirate&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Crochet de pirate.&lt;/b&gt; Les pirates qui perdent une main au cours de leurs aventures fixent parfois un crochet sur le moignon. Ses adversaires ne peuvent pas effectuer d’action pour &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Desarmement.html&quot; title=&quot;d&#233;sarmement&quot;&gt;d&#233;sarmer&lt;/a&gt; le pirate &#233;quip&#233; d’un crochet. Celui-ci ne g&#234;ne g&#233;n&#233;ralement pas le pirate dans ses activit&#233;s quotidiennes mais il ne peut ni manier une arme &#224; deux mains, ni r&#233;aliser une &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Composantes.html&quot; title=&quot;composantes&quot;&gt;composante guestuelle&lt;/a&gt; de sort, ni prendre des fl&#232;ches s’il poss&#232;de un tel crochet. Il ne peut manier aucune arme si ses deux mains ont &#233;t&#233; remplac&#233;es par des crochets et il peut rencontrer des difficult&#233;s &#224; r&#233;aliser ses activit&#233;s routini&#232;res. Le moignon au niveau du poignet doit &#234;tre intact pour pouvoir y fixer un crochet de pirate. Dans le cas contraire, utilisez &#224; la place les statistiques de la &lt;a class=&quot;pagelink&quot; href=&quot;Proth&#232;se-(Objet).html&quot; title=&quot;Proth&#232;se&quot;&gt;proth&#232;se&lt;/a&gt;. Il faut une minute pour attacher ou d&#233;tacher un crochet de pirate.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Dague&quot; href=&quot;#Dague&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Dague.&lt;/b&gt; La dague est un couteau de combat. Sa lame fait g&#233;n&#233;ralement moins de 30 centim&#232;tres de long et peut &#234;tre incurv&#233;e ou droite, avec un tranchant ou deux. La forme de la dague varie grandement et elle peut avoir diff&#233;rents noms (comme la dague d’estoc que l’on appelle parfois &#171; poignard &#187;). Le personnage re&#231;oit un bonus de +2 &#224; ses tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt; pour dissimuler une dague sur lui.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Dague coup-de-poing&quot; href=&quot;#Dague coup-de-poing&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Dague coup-de-poing.&lt;/b&gt; La lame de la dague coup-de-poing est fix&#233;e &#224; une poign&#233;e horizontale et prolonge le poing lorsqu’elle est tenue en main.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Gantelet&quot; href=&quot;#Gantelet&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Gantelet.&lt;/b&gt; Ce gant de m&#233;tal permet d’infliger des d&#233;g&#226;ts l&#233;taux plut&#244;t que des d&#233;g&#226;ts &lt;a class=&quot;pagelink&quot; href=&quot;Blessures-Et-Mort.html#NONLETAL&quot; title=&quot;Blessures et mort&quot;&gt;non l&#233;taux&lt;/a&gt; avec des &lt;a class=&quot;pagelink&quot; href=&quot;Mains-Nues-(Arme).html&quot; title=&quot;Mains nues&quot;&gt;attaques &#224; mains nues&lt;/a&gt;. Sinon, un coup port&#233; avec un gantelet est consid&#233;r&#233; comme une attaque &#224; mains nues. Le prix et le poids sont donn&#233;s pour un seul gantelet. Les &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Intermediaires.html&quot; title=&quot;armure interm&#233;diaire&quot;&gt;armures interm&#233;diaires&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Lourdes.html&quot; title=&quot;armure lourde&quot;&gt;lourdes&lt;/a&gt; (&#224; l’exception des &lt;a class=&quot;pagelink&quot; href=&quot;Cuirasse-(Armure).html&quot; title=&quot;Cuirasse&quot;&gt;cuirasses&lt;/a&gt;) sont livr&#233;es avec des gantelets. L’adversaire ne peut pas d&#233;penser une action de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Desarmement.html&quot; title=&quot;d&#233;sarmement&quot;&gt;d&#233;sarmement&lt;/a&gt; pour priver un personnage de ses gantelets.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Gantelet clout&#233;&quot; href=&quot;#Gantelet clout&#233;&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Gantelet clout&#233;.&lt;/b&gt; Il s’agit d’un gantelet en cuir &#233;pais ou en m&#233;tal avec des lames ou des pointes aux articulations, ce qui permet au personnage de poignarder ses adversaires en b&#233;n&#233;ficiant de la puissance d’un coup de poing. Le prix et le poids sont indiqu&#233;s pour un seul gantelet. Une attaque avec un gantelet clout&#233; est consid&#233;r&#233;e comme une attaque arm&#233;e. On ne peut pas &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Desarmement.html&quot; title=&quot;d&#233;sarmement&quot;&gt;d&#233;sarmer&lt;/a&gt; un personnage &#233;quip&#233; d’un gantelet &#224; pointes.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Goupillon de combat&quot; href=&quot;#Goupillon de combat&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Goupillon de combat.&lt;/b&gt; Nomm&#233;e d’apr&#232;s le goupillon ordinaire, cet outil semblable &#224; une petite masse que les pr&#234;tres utilisent pour r&#233;pandre l’&lt;a class=&quot;pagelink&quot; href=&quot;Eau-B&#233;nite-(Objet).html&quot; title=&quot;Eau b&#233;nite&quot;&gt;eau b&#233;nite&lt;/a&gt;, cette arme est pourvue d’une t&#234;te creuse que l’on peut remplir et qui se ferme avec un bouchon de m&#233;tal. Lorsque la masse frappe une cr&#233;ature, l’eau b&#233;nite jaillit par de tout petits trous perc&#233;s sur la t&#234;te de l’arme.&lt;br/&gt;&lt;br/&gt;Les cr&#233;atures sujettes aux d&#233;g&#226;ts de l’eau b&#233;nite re&#231;oivent 1 point de d&#233;g&#226;t en plus des d&#233;g&#226;ts normaux du coup de masse (un goupillon non-magique peut ainsi infliger des d&#233;g&#226;ts d’eau b&#233;nite &#224; une cr&#233;ature intangible, m&#234;me si la masse en elle-m&#234;me n’inflige aucun d&#233;g&#226;t). Apr&#232;s cinq coups, le goupillon de combat est vide et il faut le remplir de nouveau.&lt;br/&gt;&lt;br/&gt;Il faut une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; provoquant des &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;Attaque d&amp;#39;opportunit&#233; (redirection)&quot;&gt;attaques d’opportunit&#233;&lt;/a&gt; (comme le fait de boire une potion) pour le remplir d’eau b&#233;nite. Un goupillon rempli d’eau b&#233;nite se tient normalement la t&#234;te vers le haut pour &#233;viter que l’eau b&#233;nite ne s’&#233;coule lorsque l’on manie l’arme.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Hanbo&quot; href=&quot;#Hanbo&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Hanbo.&lt;/b&gt; Le hanbo est un b&#226;ton de moins d&#39;un m&#232;tre de long, souvent sculpt&#233; pour ressembler &#224; un b&#226;ton de marche.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Masse darmes l&#233;g&#232;re&quot; href=&quot;#Masse darmes l&#233;g&#232;re&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Masse d&#39;armes l&#233;g&#232;re.&lt;/b&gt; La masse d’armes l&#233;g&#232;re est faite d’une t&#234;te en m&#233;tal orn&#233; fix&#233;e sur une simple hampe de bois ou de m&#233;tal. La t&#234;te de la masse d’armes est g&#233;n&#233;ralement dot&#233;e d’ailettes pour causer davantage de douleur ou de d&#233;g&#226;ts. Certaines masses d’armes plus primitives sont faites d’une pierre reli&#233;e &#224; un manche en bois avec des lani&#232;res de cuir.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Pieu de bois&quot; href=&quot;#Pieu de bois&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Pieu de bois.&lt;/b&gt; Cette arme de combat rapproch&#233; est simplement un morceau de bois aff&#251;t&#233;. Les &lt;a class=&quot;pagelink&quot; href=&quot;Pointe-En-Fer-(Objet).html&quot; title=&quot;Pointe en fer&quot;&gt;pointes en fer&lt;/a&gt; qui sont utilis&#233;es comme armes infligent les m&#234;mes d&#233;g&#226;ts que des pieux de bois.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Serpe&quot; href=&quot;#Serpe&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Serpe.&lt;/b&gt; &#192; l’origine cette arme &#224; une main est un outil agricole utilis&#233; pour faucher le grain. Elle est pourvue d’une lame fortement incurv&#233;e capable d’accrocher facilement un membre ou l’armure de l’adversaire. La lame peut &#234;tre lisse ou dentel&#233;e, et certaines serpes de combat sont aiguis&#233;es des deux c&#244;t&#233;s de la lame au niveau de la pointe, ce qui permet de l’enfoncer plus facilement dans la chair de l’adversaire.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Armes de corps &#224; corps &#224; une main&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_de_corps_&#224;_corps_&#224;_une_main_2&quot; href=&quot;#Armes_de_corps_&#224;_corps_&#224;_une_main_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot; style=&quot;padding-right:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;&#201;pieu&quot; href=&quot;#&#201;pieu&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;&#201;pieu.&lt;/b&gt; Cette arme fait environ 90 centim&#232;tres de long, ce qui permet de l’utiliser comme &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armedejet.html&quot; title=&quot;arme de jet&quot;&gt;arme de jet&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Gourdin&quot; href=&quot;#Gourdin&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Gourdin.&lt;/b&gt; Cette arme n’est g&#233;n&#233;ralement qu’une simple pi&#232;ce de bois taill&#233;e, parfois incrust&#233;e de quelques clous ou pointes.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Gourdin mere&quot; href=&quot;#Gourdin mere&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Gourdin mere**.&lt;/b&gt; Arme de l’&#194;ge de pierre traditionnellement faite de pierre taill&#233;e, le mere est un gourdin court avec un c&#244;t&#233; plat et une pointe ac&#233;r&#233;e.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;50%&quot; style=&quot;vertical-align:top; border-left:solid 1px #002564; padding-left:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Masse darmes lourde&quot; href=&quot;#Masse darmes lourde&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Masse d&#39;armes lourde.&lt;/b&gt; La masse d’armes lourde a une t&#234;te plus grosse et un manche plus long que la &lt;a class=&quot;pagelink&quot; href=&quot;Masse-Darmes-L&#233;g&#232;re-(Arme).html&quot; title=&quot;Masse d&amp;#39;armes l&#233;g&#232;re&quot;&gt;masse d’armes l&#233;g&#232;re&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Morgenstern&quot; href=&quot;#Morgenstern&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Morgenstern.&lt;/b&gt; Le morgenstern est une boule de m&#233;tal &#224; pointes mont&#233;e sur un manche.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Armes de corps &#224; corps &#224; deux mains&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_de_corps_&#224;_corps_&#224;_deux_mains_3&quot; href=&quot;#Armes_de_corps_&#224;_corps_&#224;_deux_mains_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot; style=&quot;padding-right:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Pirates de la Mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Pirates of the Inner Sea/Pirates de la Mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoPMI.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Ba&#239;onnette&quot; href=&quot;#Ba&#239;onnette&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Ba&#239;onnette.&lt;/b&gt; Les ba&#239;onnettes sont des armes de combat rapproch&#233; pr&#233;vues pour se fixer dans la rainure ou sur le canon des arbal&#232;tes et des &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;armes &#224; feu&lt;/a&gt;. Elles permettent au personnage d’effectuer des attaques de corps &#224; corps mais cela les rend temporairement inutiles comme armes &#224; distance. Il faut une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt; pour fixer ou enlever une ba&#239;onnette.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;B&#226;ton&quot; href=&quot;#B&#226;ton&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;B&#226;ton.&lt;/b&gt; Le b&#226;ton est une simple pi&#232;ce de bois d’environ 1,50 m&#232;tre de long. En combat, on le manie en tenant une extr&#233;mit&#233; d’une main et en pla&#231;ant l’autre main &#224; un quart plus haut, ce qui permet de bloquer les coups et d’effectuer des frappes rapides.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Lance&quot; href=&quot;#Lance&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Lance.&lt;/b&gt; Une lance fait 1,50 m&#232;tre de long et peut &#234;tre lanc&#233;e.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;50%&quot; style=&quot;vertical-align:top; border-left:solid 1px #002564; padding-left:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Lance darr&#234;t&quot; href=&quot;#Lance darr&#234;t&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Lance d&#39;arr&#234;t.&lt;/b&gt; Cette lance est pourvue d’une barre d’arr&#234;t qui prot&#232;ge le personnage contre les attaquants. S’il &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Modifiant-Linitiative.html#PREPARER&quot; title=&quot;Actions modifiant l&amp;#39;initiative&quot;&gt;pr&#233;pare&lt;/a&gt; sa lance d’arr&#234;t pour recevoir une &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales#Charge.html&quot; title=&quot;charge&quot;&gt;charge&lt;/a&gt; et que son attaque r&#233;ussit, il gagne un bonus de bouclier de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; contre la cr&#233;ature qui charge jusqu’&#224; son prochain tour.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Pique&quot; href=&quot;#Pique&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Pique.&lt;/b&gt; La pique mesure environ 2,40 m&#232;tres de long.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Pirates de la Mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Pirates of the Inner Sea/Pirates de la Mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoPMI.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Pique dabordage&quot; href=&quot;#Pique dabordage&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Pique d&#39;abordage.&lt;/b&gt; Une pique d’abordage est une perche de 2,40 m&#232;tres de long dont une extr&#233;mit&#233; se termine par une pointe m&#233;tallique effil&#233;e de 30 centim&#232;tres de long. Elle ressemble beaucoup &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Pique-(Arme).html&quot; title=&quot;Pique&quot;&gt;pique&lt;/a&gt; mais la pointe m&#233;tallique est parfaitement ajust&#233;e au manche de bois, ce qui ne laisse aucune rainure ou interstice par laquelle l’eau de mer peut passer et oxyder l’arme. Cette pique est surtout mani&#233;e de mani&#232;re d&#233;fensive pour repousser les tentatives d’abordage. Elles sont fix&#233;es sur des supports autour du m&#226;t pour que les marins puissent rapidement s’en emparer et les manier pour emp&#234;cher les assaillants de sauter sur les plats-bords.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Armes &#224; distance&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_&#224;_distance_4&quot; href=&quot;#Armes_&#224;_distance_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot; style=&quot;padding-right:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Arbal&#232;te l&#233;g&#232;re&quot; href=&quot;#Arbal&#232;te l&#233;g&#232;re&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Arbal&#232;te l&#233;g&#232;re.&lt;/b&gt; Le personnage peut r&#233;armer l’arbal&#232;te l&#233;g&#232;re en tirant un levier. Le rechargement de l’arbal&#232;te l&#233;g&#232;re prend une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt; qui provoque des &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;Attaque d&amp;#39;opportunit&#233; (redirection)&quot;&gt;attaques d’opportunit&#233;&lt;/a&gt;. Elle tire des &lt;a class=&quot;pagelink&quot; href=&quot;Carreaux-Darbal&#232;te-(Arme).html&quot; title=&quot;Carreaux d&amp;#39;arbal&#232;te (10)&quot;&gt;carreaux d’arbal&#232;te&lt;/a&gt;.&lt;br/&gt;&lt;br/&gt;Normalement, l’arbal&#232;te l&#233;g&#232;re se manie &#224; deux mains, n&#233;anmoins, le personnage peut tirer avec (mais pas la recharger) d’une main avec un malus de -2 &#224; ses &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt;.&lt;br/&gt;&lt;br/&gt;Il peut tirer avec une arbal&#232;te l&#233;g&#232;re dans chaque main mais il re&#231;oit un malus aux jets d’attaque comme s’il maniait &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales.html#COMBAT2ARMES&quot; title=&quot;Actions sp&#233;ciales&quot;&gt;deux armes&lt;/a&gt; l&#233;g&#232;res. Ce malus se cumule avec celui du tir &#224; une main.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Arbal&#232;te l&#233;g&#232;re sous-marine&quot; href=&quot;#Arbal&#232;te l&#233;g&#232;re sous-marine&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Arbal&#232;te l&#233;g&#232;re sous-marine.&lt;/b&gt; Une arbal&#232;te sous-marine fonctionne comme son &lt;a class=&quot;pagelink&quot; href=&quot;Arbal&#232;te-L&#233;g&#232;re-(Arme).html&quot; title=&quot;Arbal&#232;te l&#233;g&#232;re&quot;&gt;homologue normal&lt;/a&gt; au-dessus de l’eau et s’utilise aussi sous l’eau. L&#224;, elle a un &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Facteurdeportee.html&quot; title=&quot;facteur de port&#233;e&quot;&gt;facteur de port&#233;e&lt;/a&gt; de 6 m (4 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;). Quiconque sait manier une arbal&#232;te l&#233;g&#232;re normale peut utiliser une arbal&#232;te l&#233;g&#232;re sous-marine.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Arbal&#232;te lourde&quot; href=&quot;#Arbal&#232;te lourde&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Arbal&#232;te lourde.&lt;/b&gt; Le personnage peut r&#233;armer l’arbal&#232;te lourde en actionnant un petit treuil. Le rechargement de l’arbal&#232;te lourde prend une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt; qui provoque des &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;Attaque d&amp;#39;opportunit&#233; (redirection)&quot;&gt;attaques d’opportunit&#233;&lt;/a&gt;. Elle tire des &lt;a class=&quot;pagelink&quot; href=&quot;Carreaux-Darbal&#232;te-(Arme).html&quot; title=&quot;Carreaux d&amp;#39;arbal&#232;te (10)&quot;&gt;carreaux d’arbal&#232;te&lt;/a&gt;.&lt;br/&gt;&lt;br/&gt;Normalement, le maniement de l’arbal&#232;te lourde n&#233;cessite les deux mains. N&#233;anmoins, le personnage peut tirer avec (mais pas la recharger) d’une main avec un malus de -4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt;. Il peut tirer avec une arbal&#232;te lourde dans chaque main mais il re&#231;oit un malus aux jets d’attaque comme s’il maniait &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales.html#COMBAT2ARMES&quot; title=&quot;Actions sp&#233;ciales&quot;&gt;deux armes&lt;/a&gt; &#224; une main. Ce malus se cumule avec celui du tir &#224; une main.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Arbal&#232;te lourde sous-marine&quot; href=&quot;#Arbal&#232;te lourde sous-marine&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Arbal&#232;te lourde sous-marine.&lt;/b&gt; En surface, cette arme est identique &#224; une &lt;a class=&quot;pagelink&quot; href=&quot;Arbal&#232;te-Lourde-(Arme).html&quot; title=&quot;Arbal&#232;te lourde&quot;&gt;arbal&#232;te lourde&lt;/a&gt; mais le personnage peut aussi l’utiliser sous l’eau o&#249; elle a un &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Facteurdeportee.html&quot; title=&quot;facteur de port&#233;e&quot;&gt;facteur de port&#233;e&lt;/a&gt; de 6 m&#232;tres (4 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;). Elle compte comme une arbal&#232;te lourde en ce qui concerne l’aptitude &#224; la manier et les capacit&#233;s sp&#233;ciales.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;50%&quot; style=&quot;vertical-align:top; border-left:solid 1px #002564; padding-left:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Fl&#233;chette&quot; href=&quot;#Fl&#233;chette&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Fl&#233;chette.&lt;/b&gt; Cette &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armedejet.html&quot; title=&quot;arme de jet&quot;&gt;arme de jet&lt;/a&gt; est plus grande qu’une &lt;a class=&quot;pagelink&quot; href=&quot;Fl&#232;ches-(Arme).html&quot; title=&quot;Fl&#232;ches (20)&quot;&gt;fl&#232;che&lt;/a&gt; et plus petite qu’une &lt;a class=&quot;pagelink&quot; href=&quot;Javeline-(Arme).html&quot; title=&quot;Javeline&quot;&gt;javeline&lt;/a&gt;. Elle a une extr&#233;mit&#233; lest&#233;e et une plus port&#233;e plus r&#233;duite que la javeline. La plupart des fl&#233;chettes sont des traits pourvus d’une &#233;paisse pointe en m&#233;tal.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Fronde&quot; href=&quot;#Fronde&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Fronde.&lt;/b&gt; La fronde n’est rien de plus qu’une coupe de cuir fix&#233;e &#224; deux ficelles. Le modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; du personnage s’applique aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;jets de d&#233;g&#226;ts&lt;/a&gt; de la fronde, exactement comme pour les &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armedejet.html&quot; title=&quot;arme de jet&quot;&gt;armes de jet&lt;/a&gt;. Le personnage peut tirer &#224; la fronde (mais pas la recharger) d’une main. Le rechargement de la fronde n&#233;cessite les deux mains et provoque des &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;Attaque d&amp;#39;opportunit&#233; (redirection)&quot;&gt;attaques d’opportunit&#233;&lt;/a&gt;.&lt;br/&gt;&lt;br/&gt;La fronde tire des &lt;a class=&quot;pagelink&quot; href=&quot;Billes-De-Fronde-(Arme).html&quot; title=&quot;Billes de fronde (10)&quot;&gt;billes de fronde&lt;/a&gt;. On peut lancer des pierres ordinaires avec mais elles ne sont pas aussi denses ni aussi rondes que les billes. Ainsi, elles infligent des d&#233;g&#226;ts comme si l’arme &#233;tait con&#231;ue pour une cr&#233;ature plus petite d’une cat&#233;gorie de taille que le personnage qui re&#231;oit un malus de -1 &#224; ses &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Grenade &#224; morsures&quot; href=&quot;#Grenade &#224; morsures&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Grenade &#224; morsures.&lt;/b&gt; Une grenade &#224; morsures est un sac r&#233;pugnant constitu&#233; d&#39;une t&#234;te d&#39;humano&#239;de dont le cerveau a &#233;t&#233; retir&#233; et le cr&#226;ne entaill&#233; de sorte qu&#39;il s&#39;ouvre lorsqu&#39;il est lanc&#233;. Habituellement rempli de vermines voraces, il agit comme une &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales#Armeaspersion.html&quot; title=&quot;arme &#224; aspersion&quot;&gt;arme &#224; aspersion&lt;/a&gt;. Lorsqu&#39;il touche, la vermine mord et pique la cible, infligeant 1d6 points de d&#233;g&#226;ts et for&#231;ant un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 11 pour &#233;viter d&#39;&#234;tre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Naus&#233;eux.html&quot; title=&quot;Naus&#233;eux&quot;&gt;naus&#233;eux&lt;/a&gt; pendant 1d3 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;. &#192; chaque round o&#249; une cr&#233;ature est naus&#233;euse &#224; cause d’une grenade &#224; morsures, elle subit 1 point de d&#233;g&#226;t suppl&#233;mentaire alors que la vermine continue de la mordre. Toutes les cr&#233;atures dans la zone d’aspersion subissent 1 point de d&#233;g&#226;t &#224; cause de la vermine mais ne risquent pas de devenir naus&#233;euses.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Javeline&quot; href=&quot;#Javeline&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Javeline.&lt;/b&gt; La javeline est une lance effil&#233;e. Comme elle n’est pas con&#231;ue pour le corps &#224; corps, on consid&#232;re que le personnage n’est pas form&#233; &#224; son maniement et re&#231;oit un malus de -4 &#224; ses &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; s’il utilise une javeline comme une arme de corps &#224; corps.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Sarbacane&quot; href=&quot;#Sarbacane&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Sarbacane.&lt;/b&gt; Les sarbacanes sont g&#233;n&#233;ralement utilis&#233;es pour inoculer des poisons (rarement fatals) de loin. Elles tirent pratiquement en silence. Voir la liste des &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;Les poisons  &quot;&gt;poisons&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Armes de guerre&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_de_guerre_14&quot; href=&quot;#Armes_de_guerre_14&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;h3 class=&quot;separator&quot;&gt;Armes de corps &#224; corps l&#233;g&#232;res&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_de_corps_&#224;_corps_l&#233;g&#232;res_5&quot; href=&quot;#Armes_de_corps_&#224;_corps_l&#233;g&#232;res_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot; style=&quot;padding-right:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure &#224; pointes&quot; href=&quot;#Armure &#224; pointes&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure &#224; pointes.&lt;/b&gt; On peut orner son armure de &lt;a class=&quot;pagelink&quot; href=&quot;Pointes-Darmure-(Armure).html&quot; title=&quot;Pointes d&amp;#39;armure&quot;&gt;pointes&lt;/a&gt; capables d’infliger des d&#233;g&#226;ts lors d’une &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Lutte.html&quot; title=&quot;lutte&quot;&gt;lutte&lt;/a&gt; ou d’une attaque ind&#233;pendante. On ne peut pas &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Desarmement.html&quot; title=&quot;d&#233;sarmement&quot;&gt;d&#233;sarmer&lt;/a&gt; un personnage &#233;quip&#233; de pointes d’armure.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Botte &#224; lame&quot; href=&quot;#Botte &#224; lame&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Botte &#224; lame.&lt;/b&gt; Les bottes &#224; lame poss&#232;dent un couteau &#224; ressort qui sort lorsqu&#39;il est d&#233;clench&#233; avec la bonne combinaison de pressions avec les orteils. Le personnage peut utiliser une botte &#224; lame comme &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales.html#COMBAT2ARMES&quot; title=&quot;Actions sp&#233;ciales&quot;&gt;arme secondaire&lt;/a&gt;. Faire sortir le couteau est une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; ; le r&#233;armer est une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt;. Lorsque le couteau est sorti, le personnage traite le terrain normal comme du &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;placement-Et-Position#Terraindifficile.html&quot; title=&quot;terrain difficile&quot;&gt;terrain difficile&lt;/a&gt; et le terrain difficile comme infranchissable.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Pirates de la Mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Pirates of the Inner Sea/Pirates de la Mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoPMI.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Chat &#224; neuf queues&quot; href=&quot;#Chat &#224; neuf queues&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Chat &#224; neuf queues.&lt;/b&gt; Cette arme, &#233;galement appel&#233;e &#171; fille du capitaine &#187;, est un fouet court dot&#233; de neuf lani&#232;res jalonn&#233;es de nœuds de 90 centim&#232;tres environ. Elle sert &#224; flageller et &#224; infliger de grandes souffrances sans occasionner de d&#233;g&#226;ts critiques permanents. Un chat &#224; neuf queues n’inflige aucun d&#233;g&#226;t aux cr&#233;atures dot&#233;es d’un bonus d’armure sup&#233;rieur ou &#233;gal &#224; +1 ou d’un bonus d’armure naturelle sup&#233;rieur ou &#233;gal &#224; +3.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Couteau &#224; cran darr&#234;t&quot; href=&quot;#Couteau &#224; cran darr&#234;t&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Couteau &#224; cran d&#39;arr&#234;t.&lt;/b&gt; Ce couteau poss&#232;de une lame &#224; ressort cach&#233;e &#224; l&#39;int&#233;rieur du manche. Il peut &#234;tre con&#231;u pour ressembler &#224; un autre type d&#39;objet (un test de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 15 r&#233;v&#232;le la tromperie). Si le personnage le tient en main, il peut l&#39;activer par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt;. Cette arme est trait&#233;e comme une &lt;a class=&quot;pagelink&quot; href=&quot;Dague-(Arme).html&quot; title=&quot;Dague&quot;&gt;dague&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;script&gt;
$(function () {
  let image = &quot;Illustrations/PNJ/Aquatique.jpg&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;.symbole2&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td class=&quot;symbole2&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux membres de la race indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Aquatique (race).ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/Illustrations/PNJ/Aquatique.jpg&quot; width=&quot;80%&quot; style=&quot;float:center; margin: 0px -50px 0px 7px; border: 1px solid #4b3124&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br /&gt;commune chez&lt;br /&gt;les &lt;a class=&quot;pagelink&quot; href=&quot;Aquatique-(Race).html&quot; title=&quot;Les aquatiques&quot;&gt;aquatiques&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Couteau de mer&quot; href=&quot;#Couteau de mer&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Couteau de mer.&lt;/b&gt; Le couteau de mer est une arme &#224; manche long et &#224; lame courte. Il est con&#231;u pour &#234;tre port&#233; &#224; la cheville ou au pied du porteur, la lame vers le bas, pour prolonger sa jambe. Enfiler ou retirer un couteau de mer n&#233;cessite une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt;. Le porteur ne peut pas se servir de la jambe &#224; laquelle est attach&#233; le couteau de mer pour marcher ou pour courir. Le couteau de mer peut &#234;tre utilis&#233; comme une arme de corps &#224; corps l&#233;g&#232;re lorsque le porteur nage, vole ou est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#192;terre.html&quot; title=&quot;&#192; terre&quot;&gt;&#224; terre&lt;/a&gt;. Cela lui permet d’utiliser une arme &#224; deux mains, ou de manier une arme &#224; une main et de porter un bouclier, tout en effectuant des attaques au couteau de mer de sa main non-directrice. Les attaques port&#233;es avec un couteau de mer re&#231;oivent un malus de circonstances de -2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt;, en plus de tous les autres malus.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Couteau papillon&quot; href=&quot;#Couteau papillon&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Couteau papillon*.&lt;/b&gt; Ces &#233;p&#233;es courtes assorties sont livr&#233;es par paires, astucieusement imbriqu&#233;es pour donner l’impression de ne former qu’une seule lame. On peut d&#233;gainer les deux armes &#224; la fois puis les s&#233;parer par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt; et en manier une dans chaque main pour porter des coups de taille particuli&#232;rement d&#233;vastateurs. Leur lame fine et large fait un peu plus de 30 centim&#232;tres de long.  Le couteau papillon est muni d’une poign&#233;e en bois de feuillu entour&#233;e d’une corde tress&#233;e et d’une garde m&#233;tallique en D prot&#233;geant la main du porteur. Le prix est indiqu&#233; pour une paire de couteaux papillons. Les couteaux papillons de ma&#238;tre co&#251;tent 320 po la paire. Si le personnage ajoute des bonus d’alt&#233;ration magiques ou des propri&#233;t&#233;s, traitez chacun des couteaux de la paire comme des armes distinctes (par exemple, ajouter un bonus d’alt&#233;ration magique de +1 &#224; une paire de couteaux papillons de ma&#238;tre co&#251;te 4 000 po).&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;&#201;p&#233;e courte&quot; href=&quot;#&#201;p&#233;e courte&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;&#201;p&#233;e courte.&lt;/b&gt; Ces &#233;p&#233;es font partie des armes que l’on trouve le plus couramment dans les soci&#233;t&#233;s martiales et, de ce fait, elles pr&#233;sentent des formes tr&#232;s vari&#233;es qui d&#233;pendent de leur r&#233;gion et de leur cr&#233;ateur. La plupart mesurent environ 60 centim&#232;tres de long. Leur lame peut &#234;tre incurv&#233;e ou droite, &#224; simple ou double tranchant, large ou mince. Elle peut avoir une garde orn&#233;e ou simple, avec des quillons en croix, une garde en corbeille, comme elle peut ne pas avoir de garde du tout. Ces armes sont souvent utilis&#233;es seules mais peuvent &#233;galement &#234;tre coupl&#233;es ou associ&#233;es &#224; une &lt;a class=&quot;pagelink&quot; href=&quot;Dague-(Arme).html&quot; title=&quot;Dague&quot;&gt;dague&lt;/a&gt; ou &#224; une &#233;p&#233;e plus longue.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Fl&#233;chette wushu&quot; href=&quot;#Fl&#233;chette wushu&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Fl&#233;chette wushu*.&lt;/b&gt; Cette pointe en bois aff&#251;t&#233;e peut &#234;tre utilis&#233;e comme arme pour frapper. Elle est &#233;galement parfaitement &#233;quilibr&#233;e pour le lancer.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Gladius&quot; href=&quot;#Gladius&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Gladius.&lt;/b&gt; Le gladius est l’&#233;p&#233;e pr&#233;f&#233;r&#233;e des gladiateurs. Sa lame est plus lourde que celle de l’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;p&#233;e-Courte-(Arme).html&quot; title=&quot;&#201;p&#233;e courte&quot;&gt;&#233;p&#233;e courte standard&lt;/a&gt;. Les dons et les capacit&#233;s qui affectent les &#233;p&#233;es courtes s’appliquent &#233;galement au gladius.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Pirates de la Mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Pirates of the Inner Sea/Pirates de la Mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoPMI.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Hache dabordage&quot; href=&quot;#Hache dabordage&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Hache d&#39;abordage.&lt;/b&gt; C’est une hachette dont l’arri&#232;re de la lame se termine en pointe incurv&#233;e vers le bas. Elle est utilis&#233;e pour trancher les attaches d’&#233;coutilles ou les cordages, pour saisir les d&#233;bris en feu et les jeter par-dessus bord ou pour se battre. Une hache d’abordage est une &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armedeguerre.html&quot; title=&quot;arme de guerre&quot;&gt;arme de guerre&lt;/a&gt; &#224; une main qui poss&#232;de les m&#234;mes statistiques qu’une &lt;a class=&quot;pagelink&quot; href=&quot;Hachette-(Arme).html&quot; title=&quot;Hachette&quot;&gt;hachette&lt;/a&gt;, sauf qu’elle inflige des d&#233;g&#226;ts tranchants ou perforants. De plus, la pointe conf&#232;re un bonus de circonstances de +2 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt; effectu&#233;s le long de surfaces en bois ou d&#39;autres mat&#233;riaux per&#231;ables, comme la glace.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Hache de lancer&quot; href=&quot;#Hache de lancer&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Hache de lancer.&lt;/b&gt; Cette arme &#224; une main est petite et parfaitement &#233;quilibr&#233;e pour le lancer. On peut l’utiliser comme une arme de corps &#224; corps. Les haches de lancer sont connues sous divers noms comme francisque, tomahawk, etc. La hache se tient par le manche avant d’&#234;tre lanc&#233;e, d’effectuer une rotation compl&#232;te dans les airs et d’aller se planter dans la cible au niveau du fer de hache.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Hachette&quot; href=&quot;#Hachette&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Hachette.&lt;/b&gt; Cette hache &#224; une main est assez courte (environ 30 centim&#232;tres de long) et con&#231;ue pour &#234;tre mani&#233;e &#224; une main. Contrairement aux &lt;a class=&quot;pagelink&quot; href=&quot;Hache-De-Lancer-(Arme).html&quot; title=&quot;Hache de lancer&quot;&gt;haches de lancer&lt;/a&gt;, elle n’est pas suffisamment bien &#233;quilibr&#233;e pour retomber gracieusement et elle est plus lourde au niveau du fer. Le tomahawk, la hachette de guerre et autres noms d&#233;signent g&#233;n&#233;ralement les hachettes.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Jitte&quot; href=&quot;#Jitte&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Jitte*.&lt;/b&gt; Cette arme semblable &#224; un b&#226;ton est pourvue d’un crochet en m&#233;tal que l’on peut utiliser pour bloquer l’arme d’un adversaire. Certaines variantes se terminent par une pointe ou une lame de m&#233;tal tranchant.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;50%&quot; style=&quot;vertical-align:top; border-left:solid 1px #002564; padding-left:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;K&#233;rambit&quot; href=&quot;#K&#233;rambit&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;K&#233;rambit*.&lt;/b&gt; Cette petite dague incurv&#233;e est pourvue d’une boucle en m&#233;tal &#224; la base de sa poign&#233;e, ce qui permet de la stabiliser avec un doigt ou de la porter au bout d’une ficelle attach&#233;e dans les cheveux. Si elle est relativement petite, sa lame incurv&#233;e peut infliger de violentes blessures. Facile &#224; dissimuler (le personnage gagne un bonus de +2 &#224; ses tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt; pour dissimuler un k&#233;rambit sur lui), elle constitue l’arme pr&#233;f&#233;r&#233;e des &lt;a class=&quot;pagelink&quot; href=&quot;Ninja.html&quot; title=&quot;Le ninja&quot;&gt;ninjas&lt;/a&gt; et des &lt;a class=&quot;pagelink&quot; href=&quot;Assassin.html&quot; title=&quot;L&amp;#39;assassin&quot;&gt;assassins&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Kukri&quot; href=&quot;#Kukri&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Kukri.&lt;/b&gt; Le kukri est une lame incurv&#233;e d’environ 30 centim&#232;tres de long.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;script&gt;
$(function () {
  let image = &quot;Illustrations/PNJ/Homme-rat.jpg&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;.symbole2&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td class=&quot;symbole2&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux membres de la race indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Homme-rat (race).ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/Illustrations/PNJ/Homme-rat.jpg&quot; width=&quot;80%&quot; style=&quot;float:center; margin: 0px -50px 0px 7px; border: 1px solid #4b3124&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br /&gt;commune chez&lt;br /&gt;les &lt;a class=&quot;pagelink&quot; href=&quot;Homme-Rat-(Race).html&quot; title=&quot;Les hommes-rats&quot;&gt;h-rats&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Lame caudale&quot; href=&quot;#Lame caudale&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Lame caudale.&lt;/b&gt; Une lame caudale est un petit couteau aiguis&#233; pr&#233;vu pour &#234;tre attach&#233; au bout de la queue du porteur. Il faut une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt; pour fixer ou enlever une lame caudale. Le porteur peut attacher la lame l&#226;chement par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt;, mais l’utilisation d’une lame caudale grossi&#232;rement fix&#233;e impose un malus de -4 au porteur sur tous les &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; qu’il fait avec cette arme, tandis que les autres cr&#233;atures b&#233;n&#233;ficient d’un bonus de +4 &#224; leurs tests de manœuvre offensive pour &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Desarmement.html&quot; title=&quot;d&#233;sarmement&quot;&gt;d&#233;sarmer&lt;/a&gt; la lame caudale. Un &lt;a class=&quot;pagelink&quot; href=&quot;Homme-Rat-(Race).html&quot; title=&quot;Les hommes-rats&quot;&gt;homme-rat&lt;/a&gt; maniant une lame caudale peut effectuer une attaque de queue, ajoutant son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; aux d&#233;g&#226;ts de la lame. On consid&#232;re que les hommes-rats sont form&#233;s &#224; de telles attaques et peuvent appliquer les dons ou les effets appropri&#233;s aux &lt;a class=&quot;pagelink&quot; href=&quot;Attaques-Naturelles-(Capacit&#233;).html&quot; title=&quot;Attaques naturelles&quot;&gt;attaques naturelles&lt;/a&gt; &#224; leurs attaques de queue avec une lame caudale. Si elles font partie d’une action complexe, les attaques effectu&#233;es avec une lame caudale sont consid&#233;r&#233;es comme des attaques secondaires.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Lam&#233;toile&quot; href=&quot;#Lam&#233;toile&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Lam&#233;toile.&lt;/b&gt; Cette arme se compose de quatre lames pointues en m&#233;tal sortant d’un anneau m&#233;tallique central, comme les quatre pointes d’une rose des vents. En saisissant la barre qui occupe le centre &#233;vid&#233; de l’arme, le  personnage peut frapper avec comme s’il s’agissait d’une arme de corps &#224; corps mortelle. Autrement, il peut saisir la lam&#233;toile par le bord ext&#233;rieur et lancer cette arme l&#233;g&#232;re et a&#233;rodynamique sur de courtes distances, comme un &lt;a class=&quot;pagelink&quot; href=&quot;Chakram-(Arme).html&quot; title=&quot;Chakram&quot;&gt;chakram&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Lungchuan tamo&quot; href=&quot;#Lungchuan tamo&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Lungchuan tamo*.&lt;/b&gt; Ce qui ressemble &#224; un b&#226;ton ordinaire renferme une paire de dagues &#224; fine lame assorties (des lames de jet parfaitement &#233;quilibr&#233;es).&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Marteau l&#233;ger&quot; href=&quot;#Marteau l&#233;ger&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Marteau l&#233;ger.&lt;/b&gt; Version plus l&#233;g&#232;re du &lt;a class=&quot;pagelink&quot; href=&quot;Marteau-De-Guerre-(Arme).html&quot; title=&quot;Marteau de guerre&quot;&gt;marteau de guerre&lt;/a&gt;, cette arme est g&#233;n&#233;ralement pourvue d’une t&#234;te de m&#233;tal poli avec une face pour frapper.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Matraque&quot; href=&quot;#Matraque&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Matraque.&lt;/b&gt; Cette arme se compose d’une lani&#232;re souple, g&#233;n&#233;ralement en cuir, enroul&#233;e autour d’un cœur dense et dur, g&#233;n&#233;ralement un b&#226;ton en plomb. La t&#234;te est plus large que le manche et con&#231;ue pour r&#233;partir la force du coup, rendant l’arme moins susceptible de verser le sang ou de briser les os.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Pic de guerre l&#233;ger&quot; href=&quot;#Pic de guerre l&#233;ger&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Pic de guerre l&#233;ger.&lt;/b&gt; Cette arme, d&#233;riv&#233;e de la pioche, est pourvue d&#39;une t&#234;te avec une pointe l&#233;g&#232;rement incurv&#233;e pour percer les armures et d&#39;un contrepoids semblable &#224; un marteau.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Pinceau de fer&quot; href=&quot;#Pinceau de fer&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Pinceau de fer*.&lt;/b&gt; Il s’agit d’une variante &#224; manche en fer du pinceau du savant, avec une poign&#233;e tranchante. Il n’inflige que peu de d&#233;g&#226;ts mais il se dissimule facilement (le personnage gagne un bonus de +2 &#224; ses tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt; pour cacher un pinceau de fer sur lui) et peut &#234;tre lanc&#233; sur de courtes distances ou utilis&#233; pour porter des coups sur des r&#233;seaux de nerfs cl&#233;s et des points d’acupuncture, provoquant des effets &#233;tonnamment d&#233;vastateurs.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.La Mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Inner Sea World Guide/La Mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoISWG.gif&quot; style=&quot;opacity: 0.7&quot;/&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Rasoir de combat&quot; href=&quot;#Rasoir de combat&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Rasoir de combat.&lt;/b&gt; Apparemment, un rasoir de combat est juste un rasoir ou un couteau de poche surdimensionn&#233;. Le rasoir se repliant dans son manche, il n’a pas besoin de fourreau et il est donc facile &#224; dissimuler, ce qui offre un bonus de +2 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt; pour le cacher sur soi.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Rondache&quot; href=&quot;#Rondache&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Rondache (bois/acier).&lt;/b&gt; On peut porter un coup avec une rondache plut&#244;t que de l’utiliser pour se d&#233;fendre. Les rondaches sont d&#233;crits parmi les &lt;a class=&quot;pagelink&quot; href=&quot;Rondache-(Armure).html&quot; title=&quot;Rondache (bois/acier)&quot;&gt;armures&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Rondache &#224; pointes&quot; href=&quot;#Rondache &#224; pointes&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Rondache &#224; pointes (bois/acier).&lt;/b&gt; On peut utiliser la rondache &#224; &lt;a class=&quot;pagelink&quot; href=&quot;Pointes-De-Bouclier-(Armure).html&quot; title=&quot;Pointes de bouclier&quot;&gt;pointes&lt;/a&gt; pour porter un coup plut&#244;t que pour se d&#233;fendre. On ne peut pas &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Desarmement.html&quot; title=&quot;d&#233;sarmement&quot;&gt;d&#233;sarmer&lt;/a&gt; un personnage &#233;quip&#233; d’une rondache &#224; pointes.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Shang gou&quot; href=&quot;#Shang gou&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Shang gou*.&lt;/b&gt; Forg&#233;es par paires, ces solides lames en m&#233;tal se terminent sur des crochets incurv&#233;s, tandis que leur garde est surmont&#233;e d’un croissant dont les pointes sont dirig&#233;es vers l’ext&#233;rieur. La lame en croissant de lune et la pointe sont toutes aiguis&#233;es pour le combat. Le shang gou se manie individuellement ou par paire.&lt;br/&gt;&lt;br/&gt;Ces armes gagnent l&#39;attribut sp&#233;cial de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes.html#DESARMEMENT&quot; title=&quot;Caract&#233;ristiques des armes&quot;&gt;d&#233;sarmement&lt;/a&gt; lorsqu’elles sont mani&#233;es individuellement. Le personnage peut aussi assembler une paire de shang gou pour former une seule arme &#224; une main et gagner l&#39;attribut sp&#233;cial de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes.html#CROCENJAMBE&quot; title=&quot;Caract&#233;ristiques des armes&quot;&gt;croc-en-jambe&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Tonfa&quot; href=&quot;#Tonfa&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Tonfa*.&lt;/b&gt; Ce b&#226;ton en L sert aussi bien &#224; frapper qu’&#224; bloquer. Le porteur le tient par le manche et fait tournoyer le b&#226;ton ou frappe avec le b&#226;ton couvrant son avant-bras.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;script&gt;
$(function () {
  let image = &quot;Illustrations/PNJ/Gobelin.jpg&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;.symbole2&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td class=&quot;symbole2&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux membres de la race indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Gobelin (race).ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/Illustrations/PNJ/Gobelin.jpg&quot; width=&quot;80%&quot; style=&quot;float:center; margin: 0px -50px 0px 7px; border: 1px solid #4b3124&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br /&gt;commune chez&lt;br /&gt;les &lt;a class=&quot;pagelink&quot; href=&quot;Gobelin-(Race).html&quot; title=&quot;Les gobelins&quot;&gt;gobelins&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Tranchechien&quot; href=&quot;#Tranchechien&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Tranchechien.&lt;/b&gt; Cette lame courte et incurv&#233;e a &#233;t&#233; cr&#233;&#233;e par les &lt;a class=&quot;pagelink&quot; href=&quot;Gobelin-(Race).html&quot; title=&quot;Les gobelins&quot;&gt;gobelins&lt;/a&gt; qui y percent souvent de nombreux trous pour en r&#233;duire le poids. La plupart des tranchechiens sont taill&#233;s pour les cr&#233;atures de taille P.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Armes de corps &#224; corps &#224; une main&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_de_corps_&#224;_corps_&#224;_une_main_6&quot; href=&quot;#Armes_de_corps_&#224;_corps_&#224;_une_main_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot; style=&quot;padding-right:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Canne &#233;p&#233;e&quot; href=&quot;#Canne &#233;p&#233;e&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Canne &#233;p&#233;e.&lt;/b&gt; Cette lame l&#233;g&#232;re et mince repose dans un &#233;tui en bois servant &#224; la fois de fourreau et de cachette. Il faut une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; pour d&#233;gainer cette &#233;p&#233;e (ou une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt; si le personnage a le don &lt;a class=&quot;pagelink&quot; href=&quot;Arme-En-Main.html&quot; title=&quot;Arme en main&quot;&gt;Arme en main&lt;/a&gt;). Un observateur doit r&#233;ussir un test de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 20 pour r&#233;aliser qu’une canne &#233;p&#233;e dans son fourreau est une arme et non une canne ordinaire. Le DD passe &#224; 10 si l’observateur peut manipuler la canne. Le personnage peut utiliser le don &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Finesse.html&quot; title=&quot;Attaque en finesse&quot;&gt;Attaque en finesse&lt;/a&gt; pour appliquer son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; plut&#244;t que son modificateur de Force &#224; ses &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; avec une canne &#233;p&#233;e adapt&#233;e &#224; sa taille, m&#234;me s’il ne s’agit pas d’une &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armelegere.html&quot; title=&quot;arme l&#233;g&#232;re&quot;&gt;arme l&#233;g&#232;re&lt;/a&gt;. Il n’est pas possible de manier une canne &#233;p&#233;e &#224; deux mains pour appliquer 1,5 fois son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; aux d&#233;g&#226;ts.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Cimeterre&quot; href=&quot;#Cimeterre&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Cimeterre.&lt;/b&gt; Cette &#233;p&#233;e incurv&#233;e est plus courte qu’une &lt;a class=&quot;pagelink&quot; href=&quot;&#201;p&#233;e-Longue-(Arme).html&quot; title=&quot;&#201;p&#233;e longue&quot;&gt;&#233;p&#233;e longue&lt;/a&gt; mais plus longue qu’une &lt;a class=&quot;pagelink&quot; href=&quot;&#201;p&#233;e-Courte-(Arme).html&quot; title=&quot;&#201;p&#233;e courte&quot;&gt;&#233;p&#233;e courte&lt;/a&gt;. Seul le bord ext&#233;rieur de la lame est tranchant, l’arri&#232;re est plat, la lame a donc une section triangulaire.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;&#201;cu&quot; href=&quot;#&#201;cu&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;&#201;cu (bois/acier).&lt;/b&gt; Le personnage peut porter un coup avec un &#233;cu plut&#244;t que de l’utiliser pour se d&#233;fendre. Les &#233;cus sont d&#233;crits parmi les &lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;armures&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;&#201;cu &#224; pointes&quot; href=&quot;#&#201;cu &#224; pointes&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;&#201;cu &#224; pointes (bois/acier).&lt;/b&gt; Les boucliers &#224; &lt;a class=&quot;pagelink&quot; href=&quot;Pointes-De-Bouclier-(Armure).html&quot; title=&quot;Pointes de bouclier&quot;&gt;pointes&lt;/a&gt; sont des armes impressionnantes qui peuvent n’avoir qu’une seule pointe centrale, des bords aiguis&#233;s ou tout un ensemble de pointes mortelles. On peut utiliser l’&#233;cu &#224; pointes pour porter un coup plut&#244;t que pour se d&#233;fendre. On ne peut pas &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Desarmement.html&quot; title=&quot;d&#233;sarmement&quot;&gt;d&#233;sarmer&lt;/a&gt; un personnage &#233;quip&#233; d’un &#233;cu &#224; pointes.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;&#201;p&#233;e &#224; neuf anneaux&quot; href=&quot;#&#201;p&#233;e &#224; neuf anneaux&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;&#201;p&#233;e &#224; neuf anneaux*.&lt;/b&gt; Cette arme &#224; lame large est dot&#233;e de neuf anneaux lourds r&#233;partis le long de son &#233;pine dorsale, donnant plus de poids et donc plus de force &#224; son tranchant impressionnant.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;&#201;p&#233;e longue&quot; href=&quot;#&#201;p&#233;e longue&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;&#201;p&#233;e longue.&lt;/b&gt; Cette &#233;p&#233;e mesure environ 1 m&#232;tre.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Fl&#233;au darmes l&#233;ger&quot; href=&quot;#Fl&#233;au darmes l&#233;ger&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Fl&#233;au d&#39;armes l&#233;ger.&lt;/b&gt; Il se compose d’un poids pour frapper reli&#233; au manche par une cha&#238;ne solide. Bien qu’on l’imagine souvent comme une boule, parfois &#224; pointes, comme la t&#234;te d’un &lt;a class=&quot;pagelink&quot; href=&quot;Morgenstern-(Arme).html&quot; title=&quot;Morgenstern&quot;&gt;morgenstern&lt;/a&gt;, la t&#234;te du fl&#233;au d’armes l&#233;ger peut en r&#233;alit&#233; prendre diff&#233;rentes formes, comme de petites barres. Les fl&#233;aux d’armes militaires sont des &#233;volutions plus solides des fl&#233;aux agricoles que l’on utilise pour le battage (consistant &#224; battre les piles de grains pour s&#233;parer le grain de son enveloppe).&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Fourreau de combat&quot; href=&quot;#Fourreau de combat&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Fourreau de combat.&lt;/b&gt; Ce fourreau est une &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armesimprovisees.html&quot; title=&quot;arme improvis&#233;e&quot;&gt;arme improvis&#233;e&lt;/a&gt; con&#231;ue pour permettre au personnage de le retirer de sa ceinture par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; lorsqu’il d&#233;gaine l’arme contenue &#224; l&#39;int&#233;rieur. Choisir le don &lt;a class=&quot;pagelink&quot; href=&quot;Combines-D&#233;quipement.html&quot; title=&quot;Combines d&amp;#39;&#233;quipement&quot;&gt;Combines d’&#233;quipement&lt;/a&gt; pour un fourreau offre au personnage d’autres options offensives en utilisant un fourreau. Dans le cadre des &lt;a class=&quot;pagelink&quot; href=&quot;Groupe-Darmes.html&quot; title=&quot;Les groupes d&amp;#39;arme du guerrier&quot;&gt;groupes d’armes&lt;/a&gt; du guerrier, un fourreau de lame lourde est consid&#233;r&#233; comme un &lt;a class=&quot;pagelink&quot; href=&quot;Groupe-Darmes.html#Marteaux&quot; title=&quot;Les groupes d&amp;#39;arme du guerrier&quot;&gt;marteau&lt;/a&gt;, et un fourreau de lame l&#233;g&#232;re est consid&#233;r&#233; comme une &lt;a class=&quot;pagelink&quot; href=&quot;Groupe-Darmes.html#Armesdecombatrapproch&#233;&quot; title=&quot;Les groupes d&amp;#39;arme du guerrier&quot;&gt;arme de combat rapproch&#233;&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Fourreau de combat aiguis&#233;&quot; href=&quot;#Fourreau de combat aiguis&#233;&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Fourreau de combat aiguis&#233;.&lt;/b&gt; Ce &lt;a class=&quot;pagelink&quot; href=&quot;Fourreau-De-Combat-(Arme).html&quot; title=&quot;Fourreau de combat&quot;&gt;fourreau de combat&lt;/a&gt; a une lame tranchante sur le bord ext&#233;rieur, permettant au personnage de l&#39;utiliser comme une arme classique.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Hache darmes&quot; href=&quot;#Hache darmes&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Hache d&#39;armes.&lt;/b&gt; Le manche de cette hache est suffisamment long pour que le personnage la manie &#224; une main ou &#224; deux mains. La t&#234;te peut se composer d’une lame ou de deux, leur forme allant de la demi-lune aux bords angulaires comme des versions plus &#233;troites des haches de b&#251;cheron. Le manche en bois peut &#234;tre prot&#233;g&#233; et renforc&#233; de bandes de m&#233;tal que l’on appelle des fers.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;50%&quot; style=&quot;vertical-align:top; border-left:solid 1px #002564; padding-left:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Klar&quot; href=&quot;#Klar&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Klar.&lt;/b&gt; Sous sa forme traditionnelle, cette arme tribale se compose d’une lame courte en m&#233;tal fix&#233;e au cr&#226;ne d’un grand l&#233;zard &#224; cornes mais un forgeron talentueux peut la fabriquer enti&#232;rement en m&#233;tal. Le klar traditionnel compte comme une &lt;a class=&quot;pagelink&quot; href=&quot;Rondache-(Armure).html&quot; title=&quot;Rondache (bois/acier)&quot;&gt;rondache en bois&lt;/a&gt; avec des &lt;a class=&quot;pagelink&quot; href=&quot;Armure-&#192;-Pointes-(Arme).html&quot; title=&quot;Armure &#224; pointes&quot;&gt;pointes d&#39;armure&lt;/a&gt;, le klar en m&#233;tal comme une &lt;a class=&quot;pagelink&quot; href=&quot;Rondache-(Armure).html&quot; title=&quot;Rondache (bois/acier)&quot;&gt;rondache en acier&lt;/a&gt; avec des pointes d’armure. Les klars sont trait&#233;s dans la partie &lt;a class=&quot;pagelink&quot; href=&quot;Klar-(Armure).html&quot; title=&quot;Klar&quot;&gt;boucliers&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Marteau de guerre&quot; href=&quot;#Marteau de guerre&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Marteau de guerre.&lt;/b&gt; Cette arme se compose d’un manche en bois et d’une lourde t&#234;te en m&#233;tal. La t&#234;te peut &#234;tre simple (comme un marteau de charpentier) ou double (comme une masse). Le manche est suffisamment long pour &#234;tre mani&#233; &#224; une ou &#224; deux mains. Bien que lourd et relativement lent &#224; manier, le marteau de guerre peut donner des coups puissants, broyant chair et armure.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Pic de guerre lourd&quot; href=&quot;#Pic de guerre lourd&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Pic de guerre lourd.&lt;/b&gt; Cette variante du &lt;a class=&quot;pagelink&quot; href=&quot;Pic-De-Guerre-L&#233;ger-(Arme).html&quot; title=&quot;Pic de guerre l&#233;ger&quot;&gt;pic de guerre l&#233;ger&lt;/a&gt; a un manche plus long et peut &#234;tre utilis&#233;e avec une ou deux mains. Il s&#39;agit d&#39;une arme courante et bon march&#233; pour les sodats mont&#233;s puisqu&#39;elle peut &#234;tre utilis&#233;e efficacement &#224; dos de cheval.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Rapi&#232;re&quot; href=&quot;#Rapi&#232;re&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Rapi&#232;re.&lt;/b&gt; Le personnage peut utiliser la rapi&#232;re avec le don &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Finesse.html&quot; title=&quot;Attaque en finesse&quot;&gt;Attaque en finesse&lt;/a&gt; pour appliquer son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; plut&#244;t que son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; &#224; ses &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; avec une rapi&#232;re &#224; sa taille, m&#234;me s’il ne s’agit pas d’une &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armelegere.html&quot; title=&quot;arme l&#233;g&#232;re&quot;&gt;arme l&#233;g&#232;re&lt;/a&gt;. Il n’est pas possible de manier la rapi&#232;re &#224; deux mains pour appliquer 1,5 fois son modificateur de Force aux d&#233;g&#226;ts.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Pirates de la Mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Pirates of the Inner Sea/Pirates de la Mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoPMI.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Sabre dabordage&quot; href=&quot;#Sabre dabordage&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Sabre d&#39;abordage.&lt;/b&gt; Le sabre d’abordage est une &#233;p&#233;e courte dot&#233;e d’une lame incurv&#233;e avec un seul tranchant. Les pirates appr&#233;cient cette arme car sa lame est suffisamment aff&#251;t&#233;e pour trancher les gr&#233;ements (et les voiles des navires adverses) mais suffisamment courte pour la manier lors des combats &#224; bord des navires o&#249; beaucoup d’individus s’affrontent.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Sabre double ergot de poulet&quot; href=&quot;#Sabre double ergot de poulet&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Sabre double ergot de poulet*.&lt;/b&gt; Le bout de cette &#233;p&#233;e de 90 centim&#232;tres de long &#224; lame droite est recourb&#233; en deux &#233;perons tranchants oppos&#233;s et d&#233;cal&#233;s qui servent &#224; arracher les armes des mains d’un adversaire.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Scizore&quot; href=&quot;#Scizore&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Scizore.&lt;/b&gt; Le scizore est un tube renforc&#233; qui se fixe sur l’avant-bras et se termine par une lame semi-circulaire utilis&#233;e pour porter des coups d&#233;vastateurs. Le scizore donne un bonus de bouclier de +1 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; mais, si le personnage attaque avec la lame, il perd ce bonus pour le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; et re&#231;oit un malus de -1 &#224; ses &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; avec le scizore. Lorsqu’il porte un scizore, il ne peut pas utiliser la main qui le porte pour quoi que ce soit d’autre. Le scizore donne un bonus de +10 au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; contre le &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Desarmement.html&quot; title=&quot;d&#233;sarmement&quot;&gt;d&#233;sarmement&lt;/a&gt;. Il faut une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt; pour enfiler un scizore.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Sibat&quot; href=&quot;#Sibat&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Sibat*.&lt;/b&gt; Cette arme est semblable &#224; l’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;pieu-(Arme).html&quot; title=&quot;&#201;pieu&quot;&gt;&#233;pieu&lt;/a&gt;, avec un manche en bambou ou en rotin souple et une pointe dot&#233;e de barbillons. Ces derniers peuvent se ficher dans la chair, les v&#234;tements ou l’armure de l’ennemi pour g&#234;ner ses mouvements.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Terbutje&quot; href=&quot;#Terbutje&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Terbutje**.&lt;/b&gt; Cette arme de l’&#194;ge de pierre, &#233;galement appel&#233;e macuahuitl, est constitu&#233;e d’une lame en bois tremp&#233;. Des &#233;clats ac&#233;r&#233;s de dents, d’obsidienne, de verre ou de mat&#233;riaux similaires sont fix&#233;s le long de sa lame.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Terbutje en acier&quot; href=&quot;#Terbutje en acier&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Terbutje en acier.&lt;/b&gt; Il s&#39;agit d&#39;une arme forg&#233;e con&#231;ue pour ressembler &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;Terbutje-(Arme).html&quot; title=&quot;Terbutje&quot;&gt;terbutje classique&lt;/a&gt;. Il n&#39;est pas aussi fragile que son homologue non m&#233;tallique.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Trident&quot; href=&quot;#Trident&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Trident.&lt;/b&gt; Le trident est pourvu de trois dents de m&#233;tal fix&#233;es au bout d’un b&#226;ton de 1,20 m&#232;tre de long. Cette arme peut se lancer.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Armes de corps &#224; corps &#224; deux mains&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_de_corps_&#224;_corps_&#224;_deux_mains_7&quot; href=&quot;#Armes_de_corps_&#224;_corps_&#224;_deux_mains_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot; style=&quot;padding-right:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Bardiche&quot; href=&quot;#Bardiche&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Bardiche.&lt;/b&gt; La lame de hache incurv&#233;e de cette arme d’hast est fix&#233;e au manche en deux points : le centre de la lame se fixe dans une cavit&#233; au sommet du manche, et le point le plus bas de la lame se fixe sur un support secondaire. La lame est souvent tr&#232;s longue, parfois presque aussi longue que le manche. Le personnage gagne un bonus de +2 au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; pour r&#233;sister aux tentatives de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Destruction.html&quot; title=&quot;destruction&quot;&gt;destruction&lt;/a&gt; faites contre la bardiche.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Bec de corbin&quot; href=&quot;#Bec de corbin&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Bec de corbin.&lt;/b&gt; Le bec de corbin est une arme d’hast tr&#232;s similaire au &lt;a class=&quot;pagelink&quot; href=&quot;Marteau-De-Lucerne-(Arme).html&quot; title=&quot;Marteau de Lucerne&quot;&gt;marteau de Lucerne&lt;/a&gt;, mais la t&#234;te du marteau est l&#233;g&#232;rement plus arrondie et sa pointe est plus grosse et plus crochue. Le personnage attaque surtout avec la pointe. Avec, il gagne un bonus de +2 &#224; ses tests de manœuvre offensive de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Destruction.html&quot; title=&quot;destruction&quot;&gt;destruction&lt;/a&gt; contre les armures interm&#233;diaires ou lourdes.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Briseterre&quot; href=&quot;#Briseterre&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Briseterre.&lt;/b&gt; Le m&#233;tal brut de la t&#234;te de cet &#233;norme marteau se termine sur plusieurs pointes &#233;mouss&#233;es qui aident &#224; concentrer la force d’un coup puissant sur une zone plus petite et cibl&#233;e, permettant de briser les armures plus facilement. En raison de sa grande taille et du poids de sa t&#234;te, le briseterre n’est pas tr&#232;s bien &#233;quilibr&#233;, il faut le manier &#224; deux mains pour le soulever et le contr&#244;ler correctement.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Cimeterre &#224; deux mains&quot; href=&quot;#Cimeterre &#224; deux mains&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Cimeterre &#224; deux mains.&lt;/b&gt; Cette &#233;p&#233;e a un c&#244;t&#233; tranchant incurv&#233; comme un &lt;a class=&quot;pagelink&quot; href=&quot;Cimeterre-(Arme).html&quot; title=&quot;Cimeterre&quot;&gt;cimeterre&lt;/a&gt; et un c&#244;t&#233; ext&#233;rieur non-tranchant plat ou l&#233;g&#232;rement incurv&#233;. Elle est plus lourde au niveau de la pointe, ce qui en fait une meilleure arme de taille que d’estoc.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Cors&#232;que&quot; href=&quot;#Cors&#232;que&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Cors&#232;que.&lt;/b&gt; La cors&#232;que ressemble &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;Trident-(Arme).html&quot; title=&quot;Trident&quot;&gt;trident&lt;/a&gt; mais elle n’a qu’un seul fer de lance flanqu&#233;e d’une paire de courtes lames incurv&#233;es.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;script&gt;
$(function () {
  let image = &quot;Illustrations/PNJ/Gobelin.jpg&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;.symbole2&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td class=&quot;symbole2&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux membres de la race indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Gobelin (race).ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/Illustrations/PNJ/Gobelin.jpg&quot; width=&quot;80%&quot; style=&quot;float:center; margin: 0px -50px 0px 7px; border: 1px solid #4b3124&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br /&gt;commune chez&lt;br /&gt;les &lt;a class=&quot;pagelink&quot; href=&quot;Gobelin-(Race).html&quot; title=&quot;Les gobelins&quot;&gt;gobelins&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Coupecheval&quot; href=&quot;#Coupecheval&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Coupecheval.&lt;/b&gt; Fabriqu&#233;e par les &lt;a class=&quot;pagelink&quot; href=&quot;Gobelin-(Race).html&quot; title=&quot;Les gobelins&quot;&gt;gobelins&lt;/a&gt;, cette arme est pour ainsi dire une hallebarde &#224; long manche dont la lame est pourvue d’un crochet plus grand. La plupart des coupecheval sont taill&#233;s pour les cr&#233;atures de taille P.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Coutille&quot; href=&quot;#Coutille&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Coutille.&lt;/b&gt; La coutille se compose d’une lame simple mont&#233;e au bout d’une perche d’environ 2,1 m&#232;tres de long.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Crochet ogre&quot; href=&quot;#Crochet ogre&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Crochet ogre.&lt;/b&gt; Ce gros crochet de m&#233;tal ac&#233;r&#233; permet de faire des &lt;a class=&quot;pagelink&quot; href=&quot;Croc-En-Jambe.html&quot; title=&quot;croc-en-jambe&quot;&gt;crocs-en-jambe&lt;/a&gt; et d’attraper des adversaires en fuite. Invent&#233;s par les &lt;a class=&quot;pagelink&quot; href=&quot;Ogre.html&quot; title=&quot;Ogre&quot;&gt;ogres&lt;/a&gt;, la plupart des crochets ogres sont des armes de taille G grossi&#232;rement taill&#233;es (ils sont souvent fabriqu&#233;es &#224; partir de m&#233;tal arrach&#233; sur les armes et les armures d’anciennes victimes). M&#234;me s’ils sont de pi&#232;tre qualit&#233;, les crochets ogres sont des objets de valeur en raison de leur raret&#233; et des risques &#224; courir pour s’en procurer.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;&#201;p&#233;e &#224; deux mains&quot; href=&quot;#&#201;p&#233;e &#224; deux mains&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;&#201;p&#233;e &#224; deux mains.&lt;/b&gt; Cette immense &#233;p&#233;e &#224; deux mains mesure environ 1,50 m&#232;tre de long. Il arrive qu’elle ait une lame inf&#233;rieure &#233;mouss&#233;e que l’on peut saisir.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;&#201;p&#233;e &#224; triple pointe et double tranchant&quot; href=&quot;#&#201;p&#233;e &#224; triple pointe et double tranchant&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;&#201;p&#233;e &#224; triple pointe et double tranchant*.&lt;/b&gt; L’extr&#233;mit&#233; de ce manche de 1,50 m&#232;tre est surmont&#233;e de trois longues lames incurv&#233;es vers l’ext&#233;rieur et sculpt&#233;es en forme de fleur de lotus ouverte. Sa t&#234;te d’une largeur anormale est con&#231;ue pour porter des coups puissants et causer de multiples blessures b&#233;antes qui se prolongent &#224; l’oppos&#233;e les unes des autres.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Faux&quot; href=&quot;#Faux&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Faux.&lt;/b&gt; Cette arme se compose d’un long manche de bois avec des poign&#233;es protub&#233;rantes et une lame tranchante incurv&#233;e fix&#233;e &#224; angle droit. D&#233;riv&#233;e de l’instrument agricole que l’on utilise pour faucher les bl&#233;s, la faux n&#233;cessite l’emploi des deux mains. Elle est encombrante mais capable d’infliger de graves blessures. Comme elle symbolise la mort du fait de son association avec la faucheuse, c’est une arme assez impressionnante.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Fl&#233;au darmes lourd&quot; href=&quot;#Fl&#233;au darmes lourd&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Fl&#233;au d&#39;armes lourd.&lt;/b&gt; Similaire au &lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;au-Darmes-L&#233;ger-(Arme).html&quot; title=&quot;Fl&#233;au d&amp;#39;armes l&#233;ger&quot;&gt;fl&#233;au d’armes l&#233;ger&lt;/a&gt;, le fl&#233;au d’armes lourd a une plus grosse boule de m&#233;tal et une poign&#233;e plus longue.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Fourche du tigre&quot; href=&quot;#Fourche du tigre&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Fourche du tigre*.&lt;/b&gt; Cette arme longue en forme de trident se compose d’une fourche de m&#233;tal &#224; trois dents fix&#233;e sur un manche de 2,40 m&#232;tres. On la manie essentiellement comme un b&#226;ton, le porteur saisissant le manche par le milieu et frappant avec l’extr&#233;mit&#233; fourchue. La fourche du tigre peut servir &#224; r&#233;ceptionner une &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales#Charge.html&quot; title=&quot;charge&quot;&gt;charge&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Getsugasan&quot; href=&quot;#Getsugasan&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Getsugasan*.&lt;/b&gt; Cette arme d’hast est une &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes.html#DOUBLE&quot; title=&quot;Caract&#233;ristiques des armes&quot;&gt;arme double&lt;/a&gt;. L’une des extr&#233;mit&#233;s est agr&#233;ment&#233;e d’un large lame tranchante ressemblant &#224; une pelle, tandis que l’autre est agr&#233;ment&#233;e d’une lame en croissant de lune, comme des cornes de taureau. Le getsugasan inflige de nombreux types de d&#233;g&#226;ts qui d&#233;pendent de la fa&#231;on dont on le manie, le c&#244;t&#233; pelle pouvant infliger des d&#233;g&#226;ts contondants et tranchants, le c&#244;t&#233; croissant de lune pouvant trancher et perforer.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;50%&quot; style=&quot;vertical-align:top; border-left:solid 1px #002564; padding-left:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Glaive-guisarme&quot; href=&quot;#Glaive-guisarme&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Glaive-guisarme.&lt;/b&gt; Cette arme d’hast combine la lame d’une &lt;a class=&quot;pagelink&quot; href=&quot;Coutille-(Arme).html&quot; title=&quot;Coutille&quot;&gt;coutille&lt;/a&gt; avec un vilain crochet. Un adversaire en selle touch&#233; par un glaive-guisarme re&#231;oit un malus de -2 &#224; son test d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quitation.html&quot; title=&quot;&#201;quitation&quot;&gt;&#201;quitation&lt;/a&gt; pour rester en selle.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Grande hache&quot; href=&quot;#Grande hache&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Grande hache.&lt;/b&gt; Cette hache de combat &#224; deux mains est trop lourde pour &#234;tre mani&#233;e &#224; une main. La t&#234;te peut avoir une ou deux lames, comme elle peut &#234;tre &#171; barbue &#187; (ce qui signifie crochue ou avec un bord de fuite en bas) pour maximiser la force de frappe et aider &#224; arracher les boucliers des ennemis. Le manche mesure g&#233;n&#233;ralement entre 90 centim&#232;tres et 1,20 m&#232;tre.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Guisarme&quot; href=&quot;#Guisarme&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Guisarme.&lt;/b&gt; La guisarme est une hampe de 2,40 m&#232;tres de long pourvue d’une lame et d’un crochet mont&#233;s au sommet.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Hallebarde&quot; href=&quot;#Hallebarde&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Hallebarde.&lt;/b&gt; La hallebarde est similaire &#224; une lance de 1,50 m&#232;tre de long mais elle est &#233;galement pourvue d’un petit fer de hache mont&#233;e &#224; proximit&#233; du sommet.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Lance crochue&quot; href=&quot;#Lance crochue&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Lance crochue*.&lt;/b&gt; Cette arme d’hast effil&#233;e est &#233;quip&#233;e d’un crochet que l’on utilise pour accrocher les v&#234;tements et l’armure des adversaires. La lance crochue, contrairement &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Lance-Dar&#231;on-(Arme).html&quot; title=&quot;Lance d&amp;#39;ar&#231;on&quot;&gt;lance d&#39;ar&#231;on&lt;/a&gt;, ne peut pas &#234;tre mani&#233;e &#224; une main lorsqu’on est en selle et n’inflige pas de d&#233;g&#226;ts suppl&#233;mentaires si elle est utilis&#233;e en selle.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Lance dar&#231;on&quot; href=&quot;#Lance dar&#231;on&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Lance d&#39;ar&#231;on.&lt;/b&gt; La lance d’ar&#231;on inflige le double des d&#233;g&#226;ts lorsque le personnage la manie sur le dos d’une monture qui &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales#Charge.html&quot; title=&quot;charge&quot;&gt;charge&lt;/a&gt;. En selle, il peut la manier d’une seule main.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Lance-seringue&quot; href=&quot;#Lance-seringue&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Lance-seringue.&lt;/b&gt; La lame de cette arme, &#233;galement appel&#233;e &#171; lance &#224; injection &#187;, contient un tube ou un al&#233;sage mince qui se connecte &#224; un r&#233;cipient creux juste sous la garde. Un coup r&#233;ussi avec la lance injecte le contenu liquide du r&#233;cipient (g&#233;n&#233;ralement du poison ou une potion) dans la cible. Le remplissage d&#39;une lance-seringue prend 1 minute.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Marteau de Lucerne&quot; href=&quot;#Marteau de Lucerne&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Marteau de Lucerne.&lt;/b&gt; Cette arme d’hast a une t&#234;te de marteau &#224; dents pour broyer les ennemis et une t&#234;te crochue pour perforer et d&#233;chirer les armures. Son long manche permet au porteur de mettre une force exceptionnelle &#224; ses coups. Il gagne un bonus de +2 &#224; ses tests de manoeuvre offensive de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Destruction.html&quot; title=&quot;destruction&quot;&gt;destruction&lt;/a&gt; contre les armures interm&#233;diaires et lourdes.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Massue&quot; href=&quot;#Massue&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Massue.&lt;/b&gt; Cette variante plus grosse et massive du &lt;a class=&quot;pagelink&quot; href=&quot;Gourdin-(Arme).html&quot; title=&quot;Gourdin&quot;&gt;gourdin standard&lt;/a&gt; est trop lourde pour &#234;tre mani&#233;e &#224; une main. Elle peut &#234;tre d&#233;cor&#233;e et grav&#233;e, renforc&#233;e de m&#233;tal comme elle peut &#234;tre une simple branche d’arbre. Comme les simples gourdins, les massues ont de nombreux noms, comme casse-t&#234;te, shillelagh, etc.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Mattock&quot; href=&quot;#Mattock&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Mattock**.&lt;/b&gt; Le mattock ressemble &#224; un pic de guerre &#224; deux mains mais avec une lame en forme de ciseau &#224; bois au lieu d’une pointe.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Naginata&quot; href=&quot;#Naginata&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Naginata*.&lt;/b&gt; La naginata est un b&#226;ton de 1,80 m&#232;tre de long auquel est fix&#233;e une lame d’&#233;p&#233;e, l&#233;g&#232;rement incurv&#233;e, de 60 centim&#232;tres. Le manche est pr&#233;vu pour garder le porteur hors de port&#233;e des &#233;p&#233;es et des armes plus courtes.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Nodachi&quot; href=&quot;#Nodachi&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Nodachi*.&lt;/b&gt; Cette arme tr&#232;s longue &#224; deux mains est pourvue d’une lame mince mais ac&#233;r&#233;e de 1,20 m&#232;tre. Elle est surtout utilis&#233;e par les troupes au sol pour attaquer les guerriers mont&#233;s et elle peut &#234;tre utilis&#233;e pour frapper les cavaliers sur leurs montures ou pour r&#233;ceptionner une &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales#Charge.html&quot; title=&quot;charge&quot;&gt;charge&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Rhomphaia&quot; href=&quot;#Rhomphaia&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Rhomphaia**.&lt;/b&gt; Cette arme de l’&#194;ge de bronze est une des premi&#232;res armes d’hast se composant d’une longue lame &#224; un tranchant fix&#233;e sur un solide b&#226;ton, parfois l&#233;g&#232;rement incurv&#233;e. Elle sert &#224; la fois d’arme de taille et d’estoc.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Sansetsukon&quot; href=&quot;#Sansetsukon&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Sansetsukon*.&lt;/b&gt; Aussi appel&#233;e b&#226;ton en trois parties, cette arme est divis&#233;e en trois segments de 60 centim&#232;tres reli&#233;s par une petite cha&#238;ne, ce qui donne une plus grande souplesse au porteur qu’un b&#226;ton normal et lui permet de l’agiter rapidement pour cr&#233;er un blocage d&#233;fensif, l’enrouler autour des armes et les saisir ou pour exploiter son &#233;lan via un mouvement de tourbillon afin de porter des coups puissants.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Tepoztopilli&quot; href=&quot;#Tepoztopilli&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Tepoztopilli**.&lt;/b&gt; La t&#234;te de cette arme d’hast en bois de l’&#194;ge de pierre est bord&#233;e de morceaux d&#233;chiquet&#233;s d’obsidienne, de verre, de dents ou d’autre mat&#233;riaux similaires. Sa large t&#234;te sert aussi bien pour les attaques perforantes que pour les attaques tranchantes.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Vouge&quot; href=&quot;#Vouge&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Vouge.&lt;/b&gt; La lame de cette arme d’hast est tranchante, incurv&#233;e et crochue, avec l’arri&#232;re prolong&#233; par une pointe que l’on utilise g&#233;n&#233;ralement pour bloquer et parer. Lorsqu&#39;il &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Combatsurladefensive.html&quot; title=&quot;combat sur la d&#233;fensive&quot;&gt;combat sur la d&#233;fensive&lt;/a&gt; ou en &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Defensetotale.html&quot; title=&quot;d&#233;fense totale&quot;&gt;d&#233;fense totale&lt;/a&gt;, cette arme donne au personnage un bonus de bouclier de +1 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;. Un adversaire &#224; cheval touch&#233; par une vouge re&#231;oit un malus de -1 &#224; son test d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quitation.html&quot; title=&quot;&#201;quitation&quot;&gt;&#201;quitation&lt;/a&gt; pour rester en selle.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Armes &#224; distance&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_&#224;_distance_8&quot; href=&quot;#Armes_&#224;_distance_8&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot; style=&quot;padding-right:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Amentum&quot; href=&quot;#Amentum&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Amentum.&lt;/b&gt; L’amentum est une longue lani&#232;re de cuir qui se fixe sur une &lt;a class=&quot;pagelink&quot; href=&quot;Javeline-(Arme).html&quot; title=&quot;Javeline&quot;&gt;javeline&lt;/a&gt; standard. Avant de la lancer, on enroule l’amentum autour de la hampe de la javeline. Puis le personnage lance la javeline tout en tenant l’amentum, faisant tournoyer l’arme et am&#233;liorant grandement sa port&#233;e. Il faut une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt; pour attacher un amentum &#224; une javeline et une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt; pour l’enrouler. On peut garder des javelines avec des amenta d&#233;j&#224; enroul&#233;s autour d’elles. Une javeline &#233;quip&#233;e d’un amentum est consid&#233;r&#233;e comme une &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armedeguerre.html&quot; title=&quot;arme de guerre&quot;&gt;arme de guerre&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Arc court&quot; href=&quot;#Arc court&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Arc court.&lt;/b&gt; L’arc court est fait d’une seule pi&#232;ce de bois d’environ 90 centim&#232;tres. Le personnage doit utiliser ses deux mains pour manier un arc, quelle que soit sa taille. Il peut utiliser l’arc court alors qu’il est en selle. S’il a un malus &#224; cause d’une faible valeur de Force, il l’applique aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;jets de d&#233;g&#226;ts&lt;/a&gt; de l’arc court. S’il a un bonus gr&#226;ce &#224; une valeur de Force &#233;lev&#233;, il peut l’appliquer aux jets de d&#233;g&#226;ts d’un &lt;a class=&quot;pagelink&quot; href=&quot;Arc-Court-Composite-(Arme).html&quot; title=&quot;Arc court composite&quot;&gt;arc court composite&lt;/a&gt;, mais pas d’un arc court standard. L’arc court tire des &lt;a class=&quot;pagelink&quot; href=&quot;Fl&#232;ches-(Arme).html&quot; title=&quot;Fl&#232;ches (20)&quot;&gt;fl&#232;ches&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Arc court composite&quot; href=&quot;#Arc court composite&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Arc court composite.&lt;/b&gt; Le personnage doit avoir au moins deux mains libres pour utiliser un arc, quelle que soit sa taille. Il peut utiliser un arc court composite &#224; cheval. Tous les arcs composites sont fabriqu&#233;s en fonction d’une certaine valeur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; (ce qui signifie qu’il faut disposer d’un modificateur de Force minimum pour manier l’arc correctement). Si le modificateur de Force du personnage est inf&#233;rieur au facteur de force de l’arc composite, il ne peut pas l’utiliser correctement et re&#231;oit un malus de -2 &#224; ses attaques avec l’arc. L’arc court composite par d&#233;faut n&#233;cessite un modificateur de Force de +0 ou plus pour &#234;tre utilis&#233; efficacement. On peut fabriquer un arc court composite avec un facteur de force tirant avantage d’une valeur de Force sup&#233;rieur &#224; la moyenne, cette caract&#233;ristique permet au personnage de rajouter son modificateur de Force &#224; ses &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;jets de d&#233;g&#226;ts&lt;/a&gt;, jusqu’au bonus maximum pr&#233;cis&#233; pour l’arc. Chaque point de bonus de Force accord&#233; par l’arc rajoute 75 po &#224; son prix. Si le personnage a un modificateur de Force n&#233;gatif &#224; cause d’une faible valeur de Force, il l’applique &#224; ses jets de d&#233;g&#226;ts &#224; l’arc court composite. L’arc court composite tire des &lt;a class=&quot;pagelink&quot; href=&quot;Fl&#232;ches-(Arme).html&quot; title=&quot;Fl&#232;ches (20)&quot;&gt;fl&#232;ches&lt;/a&gt;.&lt;br/&gt;&lt;br/&gt;En ce qui concerne Maniement des armes, &lt;a class=&quot;pagelink&quot; href=&quot;Arme-De-Pr&#233;dilection.html&quot; title=&quot;Arme de pr&#233;dilection&quot;&gt;Arme de pr&#233;dilection&lt;/a&gt;, et les dons similaires, l’arc court composite est consid&#233;r&#233; comme un &lt;a class=&quot;pagelink&quot; href=&quot;Arc-Court-(Arme).html&quot; title=&quot;Arc court&quot;&gt;arc court&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Arc long&quot; href=&quot;#Arc long&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Arc long.&lt;/b&gt; Mesurant presque 1,50 m&#232;tre de haut, l’arc long est fait d’une seule pi&#232;ce solide de bois soigneusement sculpt&#233;. Le personnage a besoin de ses deux mains pour manier un arc long, quelle que soit sa taille. L’arc long ne peut pas &#234;tre utilis&#233; &#224; cheval. Si le personnage a un malus de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; &#224; cause d’une faible valeur, il l’applique &#224; ses &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;jets de d&#233;g&#226;ts&lt;/a&gt; &#224; l’arc long. Il peut appliquer son modificateur de Force &#224; ses jets de d&#233;g&#226;ts &#224; l’&lt;a class=&quot;pagelink&quot; href=&quot;Arc-Long-Composite-(Arme).html&quot; title=&quot;Arc long composite&quot;&gt;arc long composite&lt;/a&gt; mais pas &#224; l’arc long normal. L’arc long tire des &lt;a class=&quot;pagelink&quot; href=&quot;Fl&#232;ches-(Arme).html&quot; title=&quot;Fl&#232;ches (20)&quot;&gt;fl&#232;ches&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Arc long composite&quot; href=&quot;#Arc long composite&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Arc long composite.&lt;/b&gt; Le personnage doit avoir au moins deux mains libres pour utiliser un arc, quelle que soit sa taille. Il peut utiliser un arc long composite &#224; cheval. Tous les arcs composites sont fabriqu&#233;s en fonction d’une certaine valeur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; (ce qui signifie qu’il faut disposer d’un modificateur de Force minimum pour manier l’arc correctement). Si le modificateur de Force du personnage est inf&#233;rieur au facteur de force de l’arc composite, il ne peut pas l’utiliser correctement et re&#231;oit un malus de -2 &#224; ses attaques avec l’arc. L’arc long composite par d&#233;faut n&#233;cessite un modificateur de Force de +0 ou plus pour &#234;tre utilis&#233; efficacement. On peut fabriquer un arc long composite avec un facteur de force tirant avantage d’une valeur de Force sup&#233;rieur &#224; la moyenne, cette caract&#233;ristique permet au personnage de rajouter son modificateur de Force &#224; ses &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;jets de d&#233;g&#226;ts&lt;/a&gt;, jusqu’au bonus maximum pr&#233;cis&#233; pour l’arc. Chaque point de bonus de Force accord&#233; par l’arc rajoute 100 po &#224; son prix. Si le personnage a un modificateur de Force n&#233;gatif &#224; cause d’une faible valeur de Force, il l’applique &#224; ses jets de d&#233;g&#226;ts &#224; l’arc long composite. L’arc long composite tire des &lt;a class=&quot;pagelink&quot; href=&quot;Fl&#232;ches-(Arme).html&quot; title=&quot;Fl&#232;ches (20)&quot;&gt;fl&#232;ches&lt;/a&gt;.&lt;br/&gt;&lt;br/&gt;En ce qui concerne Maniement des armes et les dons similaires, l’arc long composite est consid&#233;r&#233; comme un &lt;a class=&quot;pagelink&quot; href=&quot;Arc-Long-(Arme).html&quot; title=&quot;Arc long&quot;&gt;long&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;50%&quot; style=&quot;vertical-align:top; border-left:solid 1px #002564; padding-left:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Atlatl&quot; href=&quot;#Atlatl&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Atlatl**.&lt;/b&gt; Cette arme de l’&#194;ge de pierre est une fine pi&#232;ce de bois ou de ramure utilis&#233;e comme levier pour projeter un &lt;a class=&quot;pagelink&quot; href=&quot;Dard-Datlatl-(Arme).html&quot; title=&quot;Dard d&amp;#39;atlatl&quot;&gt;dard sp&#233;cialement adapt&#233;&lt;/a&gt;. L’atlatl augmente la port&#233;e du dard mais il faut le recharger comme une arme &#224; projectiles. Le modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; du personnage s’applique aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;jets de d&#233;g&#226;ts&lt;/a&gt; lorsqu’il utilise l’atlatl, exactement comme avec les &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armedejet.html&quot; title=&quot;arme de jet&quot;&gt;armes de jet&lt;/a&gt;. Il peut tirer avec l’atlatl (mais pas le recharger) d’une seule main. Le rechargement de l’atlatl prend une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt; qui n&#233;cessite l’utilisation des deux mains et provoque des &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;Attaque d&amp;#39;opportunit&#233; (redirection)&quot;&gt;attaques d’opportunit&#233;&lt;/a&gt;. On peut prendre le don &lt;a class=&quot;pagelink&quot; href=&quot;Rechargement-Rapide.html&quot; title=&quot;Rechargement rapide&quot;&gt;Rechargement rapide&lt;/a&gt; pour l’atlatl, ce qui permet au personnage de recharger un dard par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Chakram&quot; href=&quot;#Chakram&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Chakram.&lt;/b&gt; Le chakram est une &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armedejet.html&quot; title=&quot;arme de jet&quot;&gt;arme de jet&lt;/a&gt; simple, &#233;l&#233;gante et facile &#224; transporter. Il s’agit d’un disque plat en m&#233;tal &#233;vid&#233; en son centre avec un bord tranchant. Le personnage peut le manier comme une arme de corps &#224; corps mais il n’est pas pr&#233;vu pour cet usage. Le personnage re&#231;oit un malus de -1 &#224; ses &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; avec cette arme et doit r&#233;ussir un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 15 ou se couper sur la lame (1/2 d&#233;g&#226;ts, pas de modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt;). Il n’a pas besoin de faire ce jet s’il porte une &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Lourdes.html&quot; title=&quot;armure lourde&quot;&gt;armure lourde&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;script&gt;
$(function () {
  let image = &quot;Illustrations/PNJ/Svirfneblin.jpg&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;.symbole2&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td class=&quot;symbole2&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux membres de la race indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Svirfneblin (race).ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/Illustrations/PNJ/Svirfneblin.jpg&quot; width=&quot;80%&quot; style=&quot;float:center; margin: 0px -50px 0px 7px; border: 1px solid #4b3124&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br /&gt;commune chez&lt;br /&gt;les &lt;a class=&quot;pagelink&quot; href=&quot;Svirfneblin-(Race).html&quot; title=&quot;Les svirfneblins&quot;&gt;svirfneblins&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Fl&#233;chette de choc&quot; href=&quot;#Fl&#233;chette de choc&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Fl&#233;chette de choc.&lt;/b&gt; Cette fl&#233;chette en cristal cr&#233;&#233;e alchimiquement g&#233;n&#232;re une d&#233;charge &#233;lectrique lorsqu’elle est lanc&#233;e. Une cr&#233;ature frapp&#233;e par cette fl&#233;chette re&#231;oit les d&#233;g&#226;ts perforants normaux ainsi qu’1d6 points de d&#233;g&#226;ts d’&#233;lectricit&#233;. Quiconque est form&#233; au maniement des &lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;chette-(Arme).html&quot; title=&quot;Fl&#233;chette&quot;&gt;fl&#233;chettes&lt;/a&gt; peut utiliser une fl&#233;chette de choc. Une fois lanc&#233;e, la fl&#233;chette est d&#233;truite.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Hunga munga&quot; href=&quot;#Hunga munga&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Hunga munga.&lt;/b&gt; Aussi appel&#233;e mambele, danisco, goleyo, njiga ou par d’autres noms moins connus, cette dague &#224; trois lames est con&#231;ue comme une &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armedejet.html&quot; title=&quot;arme de jet&quot;&gt;arme de jet&lt;/a&gt; mais ont peut aussi s’en servir au corps &#224; corps. La forme de base, &#224; trois lames, est la plus courante, le hunga munga peut prendre de nombreuses formes.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Lance-fl&#232;che&quot; href=&quot;#Lance-fl&#232;che&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Lance-fl&#232;che*.&lt;/b&gt; &lt;div style=&quot;float:right; padding: 0 0 8px 8px&quot;&gt;
