&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Fl&#232;che fumig&#232;ne&quot; href=&quot;#Fl&#232;che fumig&#232;ne&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Fl&#232;che fumig&#232;ne.&lt;/b&gt; &lt;div style=&quot;float:right; padding: 0 0 8px 8px&quot;&gt;
